values
  ('20b8e3f3-b7ea-56ef-9a42-100e4eae68b3', '644b1914-c13c-5a1f-9d9e-86f192cd73a0', null, 'usr-slack-ian', '하루 종일 4세션 돌리는 중.....', '2026-06-26T08:50:19.599Z', '2026-06-26T08:50:19.599Z', '[{"type": "rich_text", "block_id": "4oLw/", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "하루 종일 4세션 돌리는 중....."}]}]}]'),
