  ('6d9c3efb-bfe6-5746-b27f-b581cf837b8e', 'a4f3887e-60b5-59f9-b4a2-8dd3f57ee239', null, 'usr-slack-sophia', '<@U0BA6CJBUUU> 성수 오늘 매출 1위 매장 알려줘', '2026-06-27T13:16:34.538Z', '2026-06-27T13:16:34.538Z', '[{"type": "rich_text", "block_id": "l/YfX", "elements": [{"type": "rich_text_section", "elements": [{"type": "user", "user_id": "U0BA6CJBUUU"}, {"type": "text", "text": " 성수 오늘 매출 1위 매장 알려줘"}]}]}]'),
