values
  ('7687e8cb-177c-56d5-9841-09e8b95d46cf', '6c8eb00a-f68f-5306-9d35-ae99f729e52b', '223339c1-c9c2-5b3c-9de6-34f908993fa7', 'usr-slack-velen', 'Evidence  *[1]*  - Rows: 3 - Executed at (UTC): 2026-06-12T05:10:43.884Z  WITH daily AS (SELECT DATE(r.started_at) dt, r.brand, r.store_cd, r.store_name, AVG(s.total_units) avg_units, AVG(s.in_stock_items) avg_in_stock_items, COUNT(*) runs FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.status=''success'' AND r.brand IN (''CU'',''GS25'',''7ELEVEN'') AND r.started_at &gt;= ''2026-05-23T00:00:00Z'' AND r.started_at &lt; ''2026-05-27T00:00:00Z'' GROUP BY DATE(r.started_at), r.brand, r.store_cd, r.store_name), paired AS (SELECT a.brand, a.store_cd, a.store_name, a.avg_units units_0523, b.avg_units units_0526, (b.avg_units-a.avg_units) delta_units, 100.0*(b.avg_units-a.avg_units)/NULLIF(a.avg_units,0) pct_delta, a.avg_in_stock_items in_stock_items_0523, b.avg_in_stock_items in_stock_items_0526 FROM daily a JOIN daily b ON a.brand=b.brand AND a.store_cd=b.store_cd WHERE a.dt=''2026-05-23'' AND b.dt=''2026-05-26'' AND a.runs&gt;=2 AND b.runs&gt;=2) SELECT brand, COUNT(*) paired_stores, SUM(units_0523) units_0523, SUM(units_0526) units_0526, SUM(delta_units) delta_units, ROUND(100.0*SUM(delta_units)/SUM(units_0523),2) pct_delta_units, AVG(in_stock_items_0523) avg_in_stock_items_0523, AVG(in_stock_items_0526) avg_in_stock_items_0526 FROM paired GROUP BY brand ORDER BY ABS(pct_delta_units) DESC;  *[2]*  - Rows: 27 - Executed at (UTC): 2026-06-12T05:09:18.164Z  SELECT DATE(r.started_at) AS dt, r.brand, COUNT(*) AS runs, COUNT(DISTINCT r.store_cd) AS stores, SUM(s.total_items) AS total_items, SUM(s.in_stock_items) AS in_stock_items, SUM(s.zero_stock_items) AS zero_stock_items, SUM(s.total_units) AS total_units, AVG(1.0*s.in_stock_items/NULLIF(s.total_items,0)) AS avg_in_stock_item_rate, AVG(1.0*s.total_units/NULLIF(s.total_items,0)) AS avg_units_per_item FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.status=''success'' AND r.started_at &gt;= ''2026-05-23T00:00:00Z'' AND r.started_at &lt; ''2026-05-30T00:00:00Z'' GROUP BY DATE(r.started_at), r.brand ORDER BY dt, r.brand;  *[3]*  - Rows: 30 - Executed at (UTC): 2026-06-12T05:10:43.884Z  WITH daily AS (SELECT DATE(r.started_at) dt, r.brand, r.store_cd, r.store_name, AVG(s.total_units) avg_units, AVG(s.in_stock_items) avg_in_stock_items, COUNT(*) runs FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.status=''success'' AND r.brand IN (''CU'',''GS25'',''7ELEVEN'') AND r.started_at &gt;= ''2026-05-23T00:00:00Z'' AND r.started_at &lt; ''2026-05-27T00:00:00Z'' GROUP BY DATE(r.started_at), r.brand, r.store_cd, r.store_name), paired AS (SELECT a.brand, a.store_cd, a.store_name, a.avg_units units_0523, b.avg_units units_0526, (b.avg_units-a.avg_units) delta_units, 100.0*(b.avg_units-a.avg_units)/NULLIF(a.avg_units,0) pct_delta FROM daily a JOIN daily b ON a.brand=b.brand AND a.store_cd=b.store_cd WHERE a.dt=''2026-05-23'' AND b.dt=''2026-05-26'' AND a.runs&gt;=2 AND b.runs&gt;=2) SELECT * FROM paired WHERE units_0523&gt;=1000 ORDER BY pct_delta ASC LIMIT 30;  *[4]*  - Rows: 1 - Executed at (UTC): 2026-06-12T05:08:56.496Z  SELECT MIN(started_at) AS min_started, MAX(started_at) AS max_started, COUNT(*) AS runs, COUNT(DISTINCT brand) AS brands, COUNT(DISTINCT store_cd) AS stores FROM store_inventory_runs;', '2026-06-12T10:00:15.190Z', '2026-06-12T10:00:15.190Z', '[{"type": "header", "block_id": "iOqaH", "text": {"type": "plain_text", "text": "Evidence", "emoji": true}}, {"type": "section", "block_id": "92Xen", "text": {"type": "mrkdwn", "text": "*[1]*", "verbatim": false}}, {"type": "rich_text", "block_id": "LInsf", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 3"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026