values
  ('1169807b-de63-5a9e-88de-4fb0f7d1d609', '6c8eb00a-f68f-5306-9d35-ae99f729e52b', '298ef9f2-65d0-56d2-9ef0-9994d3737f12', 'usr-slack-velen', 'Evidence  *[1]*  - Rows: 7 - Executed at (UTC): 2026-06-13T05:36:09.235Z  SELECT brand, COUNT(*) AS active_targets, SUM(CASE WHEN last_enqueued_at IS NOT NULL AND last_enqueued_at&lt;&gt;'''' THEN 1 ELSE 0 END) AS enqueued_targets, SUM(CASE WHEN last_enqueued_at IS NULL OR last_enqueued_at='''' THEN 1 ELSE 0 END) AS never_enqueued_targets, ROUND(100.0*SUM(CASE WHEN last_enqueued_at IS NULL OR last_enqueued_at='''' THEN 1 ELSE 0 END)/COUNT(*),2) AS never_enqueued_pct FROM store_inventory_schedule_targets WHERE active=1 AND status=''active'' GROUP BY brand ORDER BY active_targets DESC;  *[2]*  - Rows: 1 - Executed at (UTC): 2026-06-13T05:21:09.483Z  SELECT MIN(started_at) AS min_started, MAX(started_at) AS max_started, COUNT(*) AS runs, COUNT(DISTINCT brand || '':'' || store_cd) AS stores FROM store_inventory_runs;  *[3]*  - Rows: 7 - Executed at (UTC): 2026-06-13T05:35:35.418Z  SELECT brand, COUNT(*) AS targets, SUM(CASE WHEN active=1 AND status=''active'' THEN 1 ELSE 0 END) AS active_targets, SUM(CASE WHEN active=1 AND status=''active'' AND (last_enqueued_at IS NULL OR last_enqueued_at='''') THEN 1 ELSE 0 END) AS active_never_enqueued, MIN(last_enqueued_at) AS min_last_enqueued, MAX(last_enqueued_at) AS max_last_enqueued FROM store_inventory_schedule_targets GROUP BY brand ORDER BY active_targets DESC;  *[4]*  - Rows: 1 - Executed at (UTC): 2026-06-13T05:36:09.235Z  SELECT ROUND(AVG(s.total_items),2) AS emart24_avg_total_items_per_success_run, ROUND(AVG(s.in_stock_items),2) AS emart24_avg_in_stock_items_per_success_run, COUNT(*) AS success_summary_runs, COUNT(DISTINCT r.store_cd) AS stores_with_success_summary FROM store_inventory_run_summaries s JOIN store_inventory_runs r ON r.id=s.run_id WHERE r.brand=''EMART24'' AND r.started_at &gt;= ''2026-05-28T00:00:00Z'';  *[5]*  - Rows: 1 - Executed at (UTC): 2026-06-13T05:36:09.235Z  SELECT 4042 AS never_enqueued_emart24_targets, ROUND(4042 * AVG(s.total_items),0) AS implied_missing_item_store_observations_per_full_cycle, ROUND(4042 * AVG(s.in_stock_items),0) AS implied_missing_in_stock_item_store_observations_per_full_cycle FROM store_inventory_run_summaries s JOIN store_inventory_runs r ON r.id=s.run_id WHERE r.brand=''EMART24'' AND r.started_at &gt;= ''2026-05-28T00:00:00Z'';  *[6]*  - Rows: 1 - Executed at (UTC): 2026-06-13T05:36:22.800Z  SELECT COUNT(*) AS emart24_targets, SUM(CASE WHEN d.store_cd IS NOT NULL THEN 1 ELSE 0 END) AS targets_with_store_details, SUM(CASE WHEN d.lat IS NOT NULL AND d.lng IS NOT NULL THEN 1 ELSE 0 END) AS targets_with_geo, SUM(CASE WHEN t.last_enqueued_at IS NULL OR t.last_enqueued_at='''' THEN 1 ELSE 0 END) AS never_enqueued_targets, SUM(CASE WHEN (t.last_enqueued_at IS NULL OR t.last_enqueued_at='''') AND d.lat IS NOT NULL AND d.lng IS NOT NULL THEN 1 ELSE 0 END) AS never_enqueued_with_geo FROM store_inventory_schedule_targets t LEFT JOIN store_details d ON d.brand=t.brand AND d.store_cd=t.store_cd WHERE t.brand=''EMART24'' AND t.active=1 AND t.status=''active'';  *[7]*  - Rows: 14 - Executed at (UTC): 2026-06-13T05:36:22.800Z  SELECT SUBSTR(COALESCE(d.address,''''),1,2) AS region_prefix, COUNT(*) AS never_enqueued_targets FROM store_inventory_schedule_targets t LEFT JOIN store_details d ON d.brand=t.brand AND d.store_cd=t.store_cd WHERE t.brand=''EMART24'' AND t.active=1 AND t.status=''active'' AND (t.last_enqueued_at IS NULL OR t.last_enqueued_at='''') GROUP BY region_prefix ORDER BY never_enqueued_targets DESC LIMIT 15;  *[8]*  - Rows: 14 - Executed at (UTC): 2026-06-13T05:36:22.800Z  SELECT SUBSTR(COALESCE(d.address,''''),1,2) AS region_prefix, COUNT(*) AS enqueued_targets FROM store_inventory_schedule_targets t LEFT JOIN store_details d ON d.brand=t.brand AND d.store_cd=t.store_cd WHERE t.brand=''EMART24'' AND t.active=1 AND t.status=''active'' AND t.last_enqueued_at IS NOT NULL AND t.last_enqueued_at&l