  ('dac6451d-df40-5122-ba31-5f0637f1eb0a', '6c8eb00a-f68f-5306-9d35-ae99f729e52b', 'bda02074-444c-5ece-a9aa-9674ec1a28e1', 'usr-slack-velen', 'Evidence  *[1]*  - Rows: 1 - Executed at (UTC): 2026-06-14T08:01:01.799Z  WITH base AS (SELECT CASE WHEN date(r.started_at) &gt;= ''2026-05-24'' THEN ''current'' ELSE ''prev'' END AS period, COUNT(*) AS run_rows, COUNT(DISTINCT r.id) AS distinct_runs, COUNT(DISTINCT r.store_cd) AS stores, SUM(s.zero_stock_items) AS zero_items, SUM(s.total_items) AS total_items FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id = r.id WHERE r.status=''success'' AND r.brand=''CU'' AND r.started_at &gt;= ''2026-05-21'' AND r.started_at &lt; ''2026-05-27'' GROUP BY period), p AS (SELECT MAX(CASE WHEN period=''current'' THEN zero_items END) AS cur_zero, MAX(CASE WHEN period=''current'' THEN total_items END) AS cur_total, MAX(CASE WHEN period=''current'' THEN run_rows END) AS cur_rows, MAX(CASE WHEN period=''current'' THEN distinct_runs END) AS cur_distinct_runs, MAX(CASE WHEN period=''current'' THEN stores END) AS cur_stores, MAX(CASE WHEN period=''prev'' THEN zero_items END) AS prev_zero, MAX(CASE WHEN period=''prev'' THEN total_items END) AS prev_total, MAX(CASE WHEN period=''prev'' THEN run_rows END) AS prev_rows, MAX(CASE WHEN period=''prev'' THEN distinct_runs END) AS prev_distinct_runs, MAX(CASE WHEN period=''prev'' THEN stores END) AS prev_stores FROM base) SELECT cur_rows, cur_distinct_runs, cur_stores, cur_zero, cur_total, ROUND(100.0*cur_zero/cur_total,4) AS cur_zero_rate_pct, prev_rows, prev_distinct_runs, prev_stores, prev_zero, prev_total, ROUND(100.0*prev_zero/prev_total,4) AS prev_zero_rate_pct, cur_zero-prev_zero AS delta_zero_items, ROUND(100.0*cur_zero/cur_total - 100.0*prev_zero/prev_total,4) AS delta_abs_pp, ROUND(100.0*((1.0*cur_zero/cur_total)/(1.0*prev_zero/prev_total)-1),2) AS delta_rel_pct, ROUND((1.0*prev_zero/prev_total)*cur_total - cur_zero,0) AS avoided_zero_items_if_prev_rate FROM p  *[2]*  -