  ('93ff600c-e62f-5f5a-b474-62a14107a59c', '6c8eb00a-f68f-5306-9d35-ae99f729e52b', '666d9f72-49f4-5c4e-8e8c-73330b9ff067', 'usr-slack-velen', 'Evidence  *[1]*  - Rows: 1 - Executed at (UTC): 2026-06-15T04:06:21.726Z  WITH prev AS (SELECT COUNT(DISTINCT store_cd) AS prev_stores FROM store_inventory_runs WHERE brand=''CU'' AND started_at &gt;= ''2026-05-20T00:00:00Z'' AND started_at &lt; ''2026-05-28T00:00:00Z''), cur AS (SELECT COUNT(DISTINCT store_cd) AS cur_stores FROM store_inventory_runs WHERE brand=''CU'' AND started_at &gt;= ''2026-05-28T00:00:00Z'' AND started_at &lt; ''2026-05-30T00:00:00Z''), all_period AS (SELECT COUNT(DISTINCT store_cd) AS total_distinct_stores FROM store_inventory_runs WHERE brand=''CU'' AND started_at &gt;= ''2026-05-20T00:00:00Z'' AND started_at &lt; ''2026-05-30T00:00:00Z'') SELECT prev.prev_stores, cur.cur_stores, cur.cur_stores - prev.prev_stores AS store_coverage_delta_abs, ROUND(100.0*(1.0*cur.cur_stores/prev.prev_stores - 1),2) AS store_coverage_delta_rel_pct, all_period.total_distinct_stores, ROUND(100.0*(cur.cur_stores - prev.prev_stores)/all_period.total_distinct_stores,2) AS delta_share_of_total_period_stores_pct FROM prev, cur, all_period  *[2]*  - Rows: 2 - Executed at (UTC): 2026-06-15T04:05:28.416Z  WITH first_seen AS (SELECT brand, store_cd, MIN(substr(started_at,1,10)) AS first_dt FROM store_inventory_runs WHERE brand=''CU'' GROUP BY brand, store_cd), labeled AS (SELECT r.*, CASE WHEN f.first_dt &gt;= ''2026-05-28'' THEN ''new_first_seen_2026-05-28_29'' ELSE ''existing_seen_before_2026-05-28'' END AS store_cohort FROM store_inventory_runs r JOIN first_seen f ON r.brand=f.brand AND r.store_cd=f.store_cd WHERE r.brand=''CU'' AND r.started_at &gt;= ''2026-05-28T00:00:00Z'' AND r.started_at &lt; ''2026-05-30T00:00:00Z'') SELECT store_cohort, COUNT(DISTINCT store_cd) AS stores, COUNT(*) AS runs, SUM(item_count) AS item_rows, ROUND(1.0*SUM(item_count)/NULLIF(COUNT(*),0),2) AS avg_items_per_run, SUM(CASE WHEN status=''success'' THEN 1 ELSE 0 END) AS success_runs, SUM(CASE WHEN status=''failure'' THEN 1 ELSE 0 END) AS failure_runs, ROUND(100.0*SUM(CASE WHEN status=''success'' THEN 1 ELSE 0 END)/NULLIF(COUNT(*),0),2) AS success_rate_pct, SUM(CASE WHEN item_count=0 THEN 1 ELSE 0 END) AS zero_item_runs, ROUND(100.0*SUM(CASE WHEN item_count=0 THEN 1 ELSE 0 END)/NULLIF(COUNT(*),0),2) AS zero_item_run_rate_pct FROM labeled GROUP BY store_cohort ORDER BY store_cohort  *[3]*  - Rows: 6 - Executed at (UTC): 2026-06-15T04:06:37.319Z  WITH first_seen AS (SELECT store_cd, MIN(substr(started_at,1,10)) AS first_dt FROM store_inventory_runs WHERE brand=''CU'' GROUP BY store_cd), new_stores AS (SELECT DISTINCT r.store_cd FROM store_inventory_runs r JOIN first_seen f ON r.store_cd=f.store_cd WHERE r.brand=''CU'' AND f.first_dt &gt;= ''2026-05-28'' AND r.started_at &gt;= ''2026-05-28T00:00:00Z'' AND r.started_at &lt; ''2026-05-30T00:00:00Z''), enriched AS (SELECT n.store_cd, CASE WHEN d.address IS NULL OR d.address='''' THEN ''UNKNOWN'' ELSE substr(d.address,1, instr(d.address || '' '','' '')-1) END AS region_1 FROM new_stores n LEFT JOIN store_details d ON d.brand=''CU'' AND d.store_cd=n.store_cd), ranked AS (SELECT region_1, COUNT(DISTINCT store_cd) AS stores, ROW_NUMBER() OVER (ORDER BY COUNT(DISTINCT store_cd) DESC) AS rn FROM enriched GROUP BY region_1), bucketed AS (SELECT CASE WHEN rn &lt;= 5 THEN region_1 ELSE ''Others'' END AS region_bucket, SUM(stores) AS new_stores FROM ranked GROUP BY CASE WHEN rn &lt;= 5 THEN region_1 ELSE ''Others'' END), total AS (SELECT SUM(new_stores) AS total_new_stores FROM bucketed) SELECT region_bucket, new_stores, ROUND(100.0*new_stores/total_new_stores,2) AS share_pct, ROUND(100.0*SUM(new_stores) OVER (ORDER BY CASE WHEN region_bucket=''Others'' THEN 2 ELSE 1 END, new_stores DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)/total_new_stores,2) AS cumulative_share_pct FROM bucketed, total ORDER BY CASE WHEN region_bucket=''Others'' THEN 2 ELSE 1 END, new_stores DESC  *[4]*  - Rows: 2 - Executed at (UTC): 2026-06-15T04:06:21.726Z  WITH daily AS (SELECT brand, substr(started_at,1,10) AS dt, COUNT(DISTINCT store_cd) AS stores, COUNT(*) AS runs, SUM(item_count) AS item_rows, ROUND(1.0*SUM(item_count)/NULLIF(COUNT(', '2026-06-15T06:00:22.406Z', '2026-06-15T06:00:22.406Z', '[{"type": "header", "block_id": "E3076", "text": {"type": "plain_text", "text": "Evidence", "emoji": true}}, {"type": "section", "block_id": "rGeUF", "text": {"type": "mrkdwn", "text": "*[1]*", "verbatim": false}}, {"type": "rich_text", "block_id": "NZ980", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 1"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-15T04"}, {"type": "emoji", "name": "06"}, {"type": "text", "text": "21.726Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "COdHM", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "WITH prev AS (SELECT COUNT(DISTINCT store_cd) AS prev_stores FROM store_inventory_runs WHERE brand=''CU'' AND started_at >= ''2026-05-20T00:00:00Z'' AND started_at < ''2026-05-28T00:00:00Z''), cur AS (SELECT COUNT(DISTINCT store_cd) AS cur_stores FROM store_inventory_runs WHERE brand=''CU'' AND started_at >= ''2026-05-28T00:00:00Z'' AND started_at < ''2026-05-30T00:00:00Z''), all_period AS (SELECT COUNT(DISTINCT store_cd) AS total_distinct_stores FROM store_inventory_runs WHERE brand=''CU'' AND started_at >= ''2026-05-20T00:00:00Z'' AND started_at < ''2026-05-30T00:00:00Z'') SELECT prev.prev_stores, cur.cur_stores, cur.cur_stores - prev.prev_stores AS store_coverage_delta_abs, ROUND(100.0*(1.0*cur.cur_stores/prev.prev_stores - 1),2) AS store_coverage_delta_rel_pct, all_period.total_distinct_stores, ROUND(100.0*(cur.cur_stores - prev.prev_stores)/all_period.total_distinct_stores,2) AS delta_share_of_total_period_stores_pct FROM prev, cur, all_period"}]}]}, {"type": "section", "block_id": "hpQvG", "text": {"type": "mrkdwn", "text": "*[2]*", "verbatim": false}}, {"type": "rich_text", "block_id": "u8Ygo", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 2"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-15T04"}, {"type": "emoji", "name": "05"}, {"type": "text", "text": "28.416Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "vI3U/", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "WITH first_seen AS (SELECT brand, store_cd, MIN(substr(started_at,1,10)) AS first_dt FROM store_inventory_runs WHERE brand=''CU'' GROUP BY brand, store_cd), labeled AS (SELECT r.*, CASE WHEN f.first_dt >= ''2026-05-28'' THEN ''new_first_seen_2026-05-28_29'' ELSE ''existing_seen_before_2026-05-28'' END AS store_cohort FROM store_inventory_runs r JOIN first_seen f ON r.brand=f.brand AND r.store_cd=f.store_cd WHERE r.brand=''CU'' AND r.started_at >= ''2026-05-28T00:00:00Z'' AND r.started_at < ''2026-05-30T00:00:00Z'') SELECT store_cohort, COUNT(DISTINCT store_cd) AS stores, COUNT(*) AS runs, SUM(item_count) AS item_rows, ROUND(1.0*SUM(item_count)/NULLIF(COUNT(*),0),2) AS avg_items_per_run, SUM(CASE WHEN status=''success'' THEN 1 ELSE 0 END) AS success_runs, SUM(CASE WHEN status=''failure'' THEN 1 ELSE 0 END) AS failure_runs, ROUND(100.0*SUM(CASE WHEN status=''success'' THEN 1 ELSE 0 END)/NULLIF(COUNT(*),0),2) AS success_rate_pct, SUM(CASE WHEN item_count=0 THEN 1 ELSE 0 END) AS zero_item_runs, ROUND(100.0*SUM(CASE WHEN item_count=0 THEN 1 ELSE 0 END)/NULLIF(COUNT(*),0),2) AS zero_item_run_rate_pct FROM labeled GROUP BY store_cohort ORDER BY store_cohort"}]}]}, {"type": "section", "block_id": "hwxqn", "text": {"type": "mrkdwn", "text": "*[3]*", "verbatim": false}}, {"type": "rich_text", "block_id": "BS50p", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 6"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-15T04"}, {"type": "emoji", "name": "06"}, {"type": "text", "text": "37.319Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "h1yGr", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "WITH first_seen AS (SELECT store_cd, MIN(substr(started_at,1,10)) AS first_dt FROM store_inventory_runs WHERE brand=''CU'' GROUP BY store_cd), new_stores AS (SELECT DISTINCT r.store_cd FROM store_inventory_runs r JOIN first_seen f ON r.store_cd=f.store_cd WHERE r.brand=''CU'' AND f.first_dt >= ''2026-05-28'' AND r.started_at >= ''2026-05-28T00:00:00Z'' AND r.started_at < ''2026-05-30T00:00:00Z''), enriched AS (SELECT n.store_cd, CASE WHEN d.address IS NULL OR d.address='''' THEN ''UNKNOWN'' ELSE substr(d.address,1, instr(d.address || '' '','' '')-1) END AS region_1 FROM new_stores n LEFT JOIN store_details d ON d.brand=''CU'' AND d.store_cd=n.store_cd), ranked AS (SELECT region_1, COUNT(DISTINCT store_cd) AS stores, ROW_NUMBER() OVER (ORDER BY COUNT(DISTINCT store_cd) DESC) AS rn FROM enriched GROUP BY region_1), bucketed AS (SELECT CASE WHEN rn <= 5 THEN region_1 ELSE ''Others'' END AS region_bucket, SUM(stores) AS new_stores FROM ranked GROUP BY CASE WHEN rn <= 5 THEN region_1 ELSE ''Others'' END), total AS (SELECT SUM(new_stores) AS total_new_stores FROM bucketed) SELECT region_bucket, new_stores, ROUND(100.0*new_stores/total_new_stores,2) AS share_pct, ROUND(100.0*SUM(new_stores) OVER (ORDER BY CASE WHEN region_bucket=''Others'' THEN 2 ELSE 1 END, new_stores DESC ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW)/total_new_stores,2) AS cumulative_share_pct FROM bucketed, total ORDER BY CASE WHEN region_bucket=''Others'' THEN 2 ELSE 1 END, new_stores DESC"}]}]}, {"type": "section", "block_id": "Snh/P", "text": {"type": "mrkdwn", "text": "*[4]*", "verbatim": false}}, {"type": "rich_text", "block_id": "qzGuc", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 2"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-15T04"}, {"type": "emoji", "name": "06"}, {"type": "text", "text": "21.726Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "SqGUw", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "WITH daily AS (SELECT brand, substr(started_at,1,10) AS dt, COUNT(DISTINCT store_cd) AS stores, COUNT(*) AS runs, SUM(item_count) AS item_rows, ROUND(1.0*SUM(item_count)/NULLIF(COUNT(*),0),2) AS avg_items_per_run, SUM(CASE WHEN status=''success'' THEN 1 ELSE 0 END) AS success_runs, ROUND(100.0*SUM(CASE WHEN status=''success'' THEN 1 ELSE 0 END)/NULLIF(COUNT(*),0),2) AS success_rate_pct, ROUND(100.0*SUM(CASE WHEN item_count=0 THEN 1 ELSE 0 END)/NULLIF(COUNT(*),0),2) AS zero_item_rate_pct FROM store_inventory_runs WHERE brand=''CU'' AND started_at >= ''2026-05-20T00:00:00Z'' AND started_at < ''2026-05-30T00:00:00Z'' GROUP BY brand, dt), weekday_baseline AS (SELECT CASE cast(strftime(''%w'', dt) AS integer) WHEN 0 THEN 7 ELSE cast(strftime(''%w'', dt) AS integer) END AS dow_iso, ROUND(AVG(stores),2) AS prev_same_dow_avg_stores, ROUND(AVG(avg_items_per_run),2) AS prev_same_dow_avg_items_per_run, ROUND(AVG(success_rate_pct),2) AS prev_same_dow_success_rate_pct FROM daily WHERE dt BETWEEN ''2026-05-20'' AND ''2026-05-27'' GROUP BY dow_iso), cur AS (SELECT dt, CASE cast(strftime(''%w'', dt) AS integer) WHEN 0 THEN 7 ELSE cast(strftime(''%w'', dt) AS integer) END AS dow_iso, stores AS current_stores, avg_items_per_run AS current_avg_items_per_run, success_rate_pct AS current_success_rate_pct FROM daily WHERE dt BETWEEN ''2026-05-28'' AND ''2026-05-29'') SELECT c.dt, c.dow_iso, c.current_stores, b.prev_same_dow_avg_stores, c.current_stores - b.prev_same_dow_avg_stores AS delta_stores_abs, ROUND(100.0*(c.current_stores/b.prev_same_dow_avg_stores - 1),2) AS delta_stores_rel_pct, c.current_avg_items_per_run, b.prev_same_dow_avg_items_per_run, c.current_success_rate_pct, b.prev_same_dow_success_rate_pct FROM cur c LEFT JOIN weekday_baseline b ON c.dow_iso=b.dow_iso ORDER BY c.dt"}]}]}]'),
  ('9a671cd7-4028-597d-b548-129f613fa5c4', '6c8eb00a-f68f-5306-9d35-ae99f729e52b', 'c80fd768-f417-5dad-b502-e21cfbd383a0', 'usr-slack-velen', '상위 5개 점포의 재고 units 증가폭은 각각 *CU 13324 +3,890.5*, *CU 30503 +3,695.1*, *CU 49425 +2,473.5*, *CU 03264 +2,293.6*, *CU 45353 +2,099.6*으로 확인됩니다 [3]. 해당 점포명과 주소 기준 강남구 여부, 24시간 운영 여부, delivery_yn 값은 점포 상세 정보에서 확인됐습니다 [2].  해석상 주의점  이번 근거에는 판매량, 주문수, 매출 데이터가 포함되어 있지 않으므로 *수요 증가로 단정하면 안 됩니다*. 현재 확인 가능한 결론은 CU 비교 가능 점포군, 특히 강남권 증가 상위 점포에서 *재고 units와 item/in-stock item 지표의 증가가 관측됐다*는 점입니다 [1] [3].  또한 SKU 상세 결과는 현재 *0 rows*로 확인되어 특정 SKU 또는 카테고리 확대를 추천하기에는 근거가 부족합니다 [4] [5].  권고 조치  1. 운영/리테일 담당자는 CU 13324, 30503, 49425, 03264, 45353의 발주·보충 정책을 점검해, 관측된 증가가 의도된 재고 보강인지 일시적 과잉 보충인지 확인하세요 [3] [2]. 2. 온라인/배달 채널 담당자는 상위 5개 중 delivery_yn=Y인 4개 점포에 한해 앱/배달 채널의 노출 확대 테스트를 진행하고, delivery_yn=N인 CU 03264는 오프라인 운영 점검 대상으로 분리하세요 [2]. 3. 데이터/수집 담당자는 store_inventory_snapshots의 SKU 상세 수집을 복구한 뒤, 같은 기간·점포 기준으로 SKU, 카테고리, in-stock 상태, 가격대별 후속 분석을 수행하세요 [4] [5].', '2026-06-15T10:00:13.871Z', '2026-06-15T10:00:13.871Z', '[{"type": "section", "block_id": "QfXiv", "text": {"type": "mrkdwn", "text": "상위 5개 점포의 재고 units 증가폭은 각각 *CU 13324 +3,890.5*, *CU 30503 +3,695.1*, *CU 49425 +2,473.5*, *CU 03264 +2,293.6*, *CU 45353 +2,099.6*으로 확인됩니다 [3]. 해당 점포명과 주소 기준 강남구 여부, 24시간 운영 여부, delivery_yn 값은 점포 상세 정보에서 확인됐습니다 [2].", "verbatim": false}}, {"type": "header", "block_id": "MfnqL", "text": {"type": "plain_text", "text": "해석상 주의점", "emoji": true}}, {"type": "section", "block_id": "VVDWM", "text": {"type": "mrkdwn", "text": "이번 근거에는 판매량, 주문수, 매출 데이터가 포함되어 있지 않으므로 *수요 증가로 단정하면 안 됩니다*. 현재 확인 가능한 결론은 CU 비교 가능 점포군, 특히 강남권 증가 상위 점포에서 *재고 units와 item/in-stock item 지표의 증가가 관측됐다*는 점입니다 [1] [3].", "verbatim": false}}, {"type": "section", "block_id": "MlXyf", "text": {"type": "mrkdwn", "text": "또한 SKU 상세 결과는 현재 *0 rows*로 확인되어 특정 SKU 또는 카테고리 확대를 추천하기에는 근거가 부족합니다 [4] [5].", "verbatim": false}}, {"type": "header", "block_id": "/AUaH", "text": {"type": "plain_text", "text": "권고 조치", "emoji": true}}, {"type": "rich_text", "block_id": "WC+Ha", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "운영/리테일 담당자", "style": {"bold": true}}, {"type": "text", "text": "는 CU 13324, 30503, 49425, 03264, 45353의 "}, {"type": "text", "text": "발주·보충 정책", "style": {"bold": true}}, {"type": "text", "text": "을 점검해, 관측된 증가가 의도된 재고 보강인지 일시적 과잉 보충인지 확인하세요 [3] [2]."}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "온라인/배달 채널 담당자", "style": {"bold": true}}, {"type": "text", "text": "는 상위 5개 중 "}, {"type": "text", "text": "delivery_yn=Y인 4개 점포", "style": {"bold": true}}, {"type": "text", "text": "에 한해 앱/배달 채널의 노출 확대 테스트를 진행하고, "}, {"type": "text", "text": "delivery_yn=N인 CU 03264", "style": {"bold": true}}, {"type": "text", "text": "는 오프라인 운영 점검 대상으로 분리하세요 [2]."}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "데이터/수집 담당자", "style": {"bold": true}}, {"type": "text", "text": "는 "}, {"type": "text", "text": "store_inventory_snapshots", "style": {"code": true}}, {"type": "text", "text": "의 SKU 상세 수집을 복구한 뒤, 같은 기간·점포 기준으로 SKU, 카테고리, in-stock 상태, 가격대별 후속 분석을 수행하세요 [4] [5]."}]}], "style": "ordered", "indent": 0}]}]')
on conflict (id) do nothing;

insert into briar_channel_messages (id, channel_id, parent_message_id, author_user_id, body, created_at, updated_at, blocks_json)
values
  ('2aa2ca49-6611-5a38-af90-58da3e268450', '6c8eb00a-f68f-5306-9d35-ae99f729e52b', 'c80fd768-f417-5dad-b502-e21cfbd383a0', 'usr-slack-velen', 'Evidence  *[1]*  - Rows: 2 - Executed at (UTC): 2026-06-15T07:58:37.350Z  WITH daily AS (SELECT s.brand, s.store_cd, date(r.started_at) AS dt, AVG(s.total_units) AS avg_units, AVG(s.total_items) AS avg_items, AVG(s.in_stock_items) AS avg_in_stock, COUNT(*) AS runs FROM store_inventory_run_summaries s JOIN store_inventory_runs r ON r.id=s.run_id WHERE r.status=''success'' AND r.started_at &gt;= ''2026-05-07T00:00:00Z'' AND r.started_at &lt; ''2026-05-30T00:00:00Z'' GROUP BY s.brand, s.store_cd, date(r.started_at) HAVING COUNT(*) &gt;= 2), early AS (SELECT brand, store_cd, AVG(avg_units) AS early_units, AVG(avg_items) AS early_items, AVG(avg_in_stock) AS early_in_stock, COUNT(*) AS early_days FROM daily WHERE dt BETWEEN ''2026-05-07'' AND ''2026-05-13'' GROUP BY brand, store_cd), late AS (SELECT brand, store_cd, AVG(avg_units) AS late_units, AVG(avg_items) AS late_items, AVG(avg_in_stock) AS late_in_stock, COUNT(*) AS late_days FROM daily WHERE dt BETWEEN ''2026-05-23'' AND ''2026-05-29'' GROUP BY brand, store_cd) SELECT e.brand, COUNT(*) AS comparable_stores, SUM(e.early_units) AS early_units_sum, SUM(l.late_units) AS late_units_sum, (SUM(l.late_units)-SUM(e.early_units)) AS units_change, (SUM(l.late_units)-SUM(e.early_units))*1.0/SUM(e.early_units) AS units_change_pct, AVG(e.early_items) AS avg_early_items, AVG(l.late_items) AS avg_late_items, AVG(e.early_in_stock) AS avg_early_in_stock, AVG(l.late_in_stock) AS avg_late_in_stock FROM early e JOIN late l ON l.brand=e.brand AND l.store_cd=e.store_cd WHERE e.early_days &gt;= 2 AND l.late_days &gt;= 2 AND e.early_units &gt; 0 GROUP BY e.brand ORDER BY ABS(units_change_pct) DESC;  *[2]*  - Rows: 5 - Executed at (UTC): 2026-06-15T07:58:58.272Z  SELECT brand, store_cd, store_name, address, hour24_yn, delivery_yn, pickup_yn, storeplus_yn FROM store_details WHERE brand=''CU'' AND store_cd IN (''13324'',''30503'',''49425'',''03264'',''45353'') ORDER BY store_cd;  *[3]*  - Rows: 30 - Executed at (UTC): 2026-06-15T07:58:37.350Z  WITH daily AS (SELECT s.brand, s.store_cd, date(r.started_at) AS dt, AVG(s.total_units) AS avg_units, AVG(s.total_items) AS avg_items, AVG(s.in_stock_items) AS avg_in_stock, COUNT(*) AS runs FROM store_inventory_run_summaries s JOIN store_inventory_runs r ON r.id=s.run_id WHERE r.status=''success'' AND r.started_at &gt;= ''2026-05-07T00:00:00Z'' AND r.started_at &lt; ''2026-05-30T00:00:00Z'' GROUP BY s.brand, s.store_cd, date(r.started_at) HAVING COUNT(*) &gt;= 2), early AS (SELECT brand, store_cd, AVG(avg_units) AS early_units, AVG(avg_items) AS early_items, AVG(avg_in_stock) AS early_in_stock, COUNT(*) AS early_days FROM daily WHERE dt BETWEEN ''2026-05-07'' AND ''2026-05-13'' GROUP BY brand, store_cd), late AS (SELECT brand, store_cd, AVG(avg_units) AS late_units, AVG(avg_items) AS late_items, AVG(avg_in_stock) AS late_in_stock, COUNT(*) AS late_days FROM daily WHERE dt BETWEEN ''2026-05-23'' AND ''2026-05-29'' GROUP BY brand, store_cd) SELECT e.brand, e.store_cd, e.early_days, l.late_days, e.early_units, l.late_units, (l.late_units-e.early_units) AS units_change, (l.late_units-e.early_units)*1.0/e.early_units AS units_change_pct, e.early_items, l.late_items, e.early_in_stock, l.late_in_stock FROM early e JOIN late l ON l.brand=e.brand AND l.store_cd=e.store_cd WHERE e.early_days &gt;= 2 AND l.late_days &gt;= 2 AND e.early_units &gt; 0 ORDER BY units_change DESC LIMIT 30;  *[4]*  - Rows: 0 - Executed at (UTC): 2026-06-15T07:58:58.272Z  WITH period_item AS (SELECT i.brand, i.store_cd, i.disp_large_cd, CASE WHEN date(r.started_at) BETWEEN ''2026-05-07'' AND ''2026-05-13'' THEN ''early'' WHEN date(r.started_at) BETWEEN ''2026-05-23'' AND ''2026-05-29'' THEN ''late'' END AS period, AVG(COALESCE(i.stock,0)) AS avg_stock, AVG(CASE WHEN COALESCE(i.stock,0)&gt;0 THEN 1 ELSE 0 END) AS instock_rate, COUNT(*) AS obs FROM store_inventory_snapshots i JOIN store_inventory_runs r ON r.id=i.run_id WHERE r.status=''success'' AND i.brand=''CU'' AND i.store_cd=''30503'' AND ((date(r.started_at) BETWEEN ''2026-05-07'' AND ''2026-05-13'') OR (date(r.started_at) BETWEEN ''2026-05-23', '2026-06-15T10:00:14.068Z', '2026-06-15T10:00:14.068Z', '[{"type": "header", "block_id": "0OZiy", "text": {"type": "plain_text", "text": "Evidence", "emoji": true}}, {"type": "section", "block_id": "SMDby", "text": {"type": "mrkdwn", "text": "*[1]*", "verbatim": false}}, {"type": "rich_text", "block_id": "lANpx", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 2"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-15T07"}, {"type": "emoji", "name": "58"}, {"type": "text", "text": "37.350Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "vr/fi", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "WITH daily AS (SELECT s.brand, s.store_cd, date(r.started_at) AS dt, AVG(s.total_units) AS avg_units, AVG(s.total_items) AS avg_items, AVG(s.in_stock_items) AS avg_in_stock, COUNT(*) AS runs FROM store_inventory_run_summaries s JOIN store_inventory_runs r ON r.id=s.run_id WHERE r.status=''success'' AND r.started_at >= ''2026-05-07T00:00:00Z'' AND r.started_at < ''2026-05-30T00:00:00Z'' GROUP BY s.brand, s.store_cd, date(r.started_at) HAVING COUNT(*) >= 2), early AS (SELECT brand, store_cd, AVG(avg_units) AS early_units, AVG(avg_items) AS early_items, AVG(avg_in_stock) AS early_in_stock, COUNT(*) AS early_days FROM daily WHERE dt BETWEEN ''2026-05-07'' AND ''2026-05-13'' GROUP BY brand, store_cd), late AS (SELECT brand, store_cd, AVG(avg_units) AS late_units, AVG(avg_items) AS late_items, AVG(avg_in_stock) AS late_in_stock, COUNT(*) AS late_days FROM daily WHERE dt BETWEEN ''2026-05-23'' AND ''2026-05-29'' GROUP BY brand, store_cd) SELECT e.brand, COUNT(*) AS comparable_stores, SUM(e.early_units) AS early_units_sum, SUM(l.late_units) AS late_units_sum, (SUM(l.late_units)-SUM(e.early_units)) AS units_change, (SUM(l.late_units)-SUM(e.early_units))*1.0/SUM(e.early_units) AS units_change_pct, AVG(e.early_items) AS avg_early_items, AVG(l.late_items) AS avg_late_items, AVG(e.early_in_stock) AS avg_early_in_stock, AVG(l.late_in_stock) AS avg_late_in_stock FROM early e JOIN late l ON l.brand=e.brand AND l.store_cd=e.store_cd WHERE e.early_days >= 2 AND l.late_days >= 2 AND e.early_units > 0 GROUP BY e.brand ORDER BY ABS(units_change_pct) DESC;"}]}]}, {"type": "section", "block_id": "rTpTw", "text": {"type": "mrkdwn", "text": "*[2]*", "verbatim": false}}, {"type": "rich_text", "block_id": "fxm+s", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 5"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-15T07"}, {"type": "emoji", "name": "58"}, {"type": "text", "text": "58.272Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "MvO2d", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "SELECT brand, store_cd, store_name, address, hour24_yn, delivery_yn, pickup_yn, storeplus_yn FROM store_details WHERE brand=''CU'' AND store_cd IN (''13324'',''30503'',''49425'',''03264'',''45353'') ORDER BY store_cd;"}]}]}, {"type": "section", "block_id": "fVhBR", "text": {"type": "mrkdwn", "text": "*[3]*", "verbatim": false}}, {"type": "rich_text", "block_id": "p6g/y", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 30"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-15T07"}, {"type": "emoji", "name": "58"}, {"type": "text", "text": "37.350Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "Apaxi", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "WITH daily AS (SELECT s.brand, s.store_cd, date(r.started_at) AS dt, AVG(s.total_units) AS avg_units, AVG(s.total_items) AS avg_items, AVG(s.in_stock_items) AS avg_in_stock, COUNT(*) AS runs FROM store_inventory_run_summaries s JOIN store_inventory_runs r ON r.id=s.run_id WHERE r.status=''success'' AND r.started_at >= ''2026-05-07T00:00:00Z'' AND r.started_at < ''2026-05-30T00:00:00Z'' GROUP BY s.brand, s.store_cd, date(r.started_at) HAVING COUNT(*) >= 2), early AS (SELECT brand, store_cd, AVG(avg_units) AS early_units, AVG(avg_items) AS early_items, AVG(avg_in_stock) AS early_in_stock, COUNT(*) AS early_days FROM daily WHERE dt BETWEEN ''2026-05-07'' AND ''2026-05-13'' GROUP BY brand, store_cd), late AS (SELECT brand, store_cd, AVG(avg_units) AS late_units, AVG(avg_items) AS late_items, AVG(avg_in_stock) AS late_in_stock, COUNT(*) AS late_days FROM daily WHERE dt BETWEEN ''2026-05-23'' AND ''2026-05-29'' GROUP BY brand, store_cd) SELECT e.brand, e.store_cd, e.early_days, l.late_days, e.early_units, l.late_units, (l.late_units-e.early_units) AS units_change, (l.late_units-e.early_units)*1.0/e.early_units AS units_change_pct, e.early_items, l.late_items, e.early_in_stock, l.late_in_stock FROM early e JOIN late l ON l.brand=e.brand AND l.store_cd=e.store_cd WHERE e.early_days >= 2 AND l.late_days >= 2 AND e.early_units > 0 ORDER BY units_change DESC LIMIT 30;"}]}]}, {"type": "section", "block_id": "DIfax", "text": {"type": "mrkdwn", "text": "*[4]*", "verbatim": false}}, {"type": "rich_text", "block_id": "6+wVT", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 0"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-15T07"}, {"type": "emoji", "name": "58"}, {"type": "text", "text": "58.272Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "H7mI+", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "WITH period_item AS (SELECT i.brand, i.store_cd, i.disp_large_cd, CASE WHEN date(r.started_at) BETWEEN ''2026-05-07'' AND ''2026-05-13'' THEN ''early'' WHEN date(r.started_at) BETWEEN ''2026-05-23'' AND ''2026-05-29'' THEN ''late'' END AS period, AVG(COALESCE(i.stock,0)) AS avg_stock, AVG(CASE WHEN COALESCE(i.stock,0)>0 THEN 1 ELSE 0 END) AS instock_rate, COUNT(*) AS obs FROM store_inventory_snapshots i JOIN store_inventory_runs r ON r.id=i.run_id WHERE r.status=''success'' AND i.brand=''CU'' AND i.store_cd=''30503'' AND ((date(r.started_at) BETWEEN ''2026-05-07'' AND ''2026-05-13'') OR (date(r.started_at) BETWEEN ''2026-05-23'' AND ''2026-05-29'')) GROUP BY i.brand, i.store_cd, i.disp_large_cd, i.item_cd, i.on_item_no, period), cat AS (SELECT disp_large_cd, period, SUM(avg_stock) AS period_units, COUNT(*) AS item_count, SUM(CASE WHEN instock_rate>0 THEN 1 ELSE 0 END) AS items_seen_instock FROM period_item WHERE period IS NOT NULL GROUP BY disp_large_cd, period), wide AS (SELECT COALESCE(e.disp_large_cd,l.disp_large_cd) AS disp_large_cd, e.period_units AS early_units, l.period_units AS late_units, (l.period_units - e.period_units) AS units_change, (l.period_units-e.period_units)*1.0/NULLIF(e.period_units,0) AS units_change_pct, e.item_count AS early_items, l.item_count AS late_items FROM cat e JOIN cat l ON e.disp_large_cd=l.disp_large_cd AND e.period=''early'' AND l.period=''late'') SELECT * FROM wide ORDER BY units_change DESC LIMIT 20;"}]}]}, {"type": "section", "block_id": "xB93X", "text": {"type": "mrkdwn", "text": "*[5]*", "verbatim": false}}, {"type": "rich_text", "block_id": "o4bMQ", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 0"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-15T07"}, {"type": "emoji", "name": "58"}, {"type": "text", "text": "58.272Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "JnISY", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "WITH period_item AS (SELECT i.item_cd, i.on_item_no, i.item_name, i.disp_large_cd, CASE WHEN date(r.started_at) BETWEEN ''2026-05-07'' AND ''2026-05-13'' THEN ''early'' WHEN date(r.started_at) BETWEEN ''2026-05-23'' AND ''2026-05-29'' THEN ''late'' END AS period, AVG(COALESCE(i.stock,0)) AS avg_stock, COUNT(*) AS obs FROM store_inventory_snapshots i JOIN store_inventory_runs r ON r.id=i.run_id WHERE r.status=''success'' AND i.brand=''CU'' AND i.store_cd=''30503'' AND ((date(r.started_at) BETWEEN ''2026-05-07'' AND ''2026-05-13'') OR (date(r.started_at) BETWEEN ''2026-05-23'' AND ''2026-05-29'')) GROUP BY i.item_cd, i.on_item_no, i.item_name, i.disp_large_cd, period), wide AS (SELECT e.item_cd, e.on_item_no, e.item_name, e.disp_large_cd, e.avg_stock AS early_stock, l.avg_stock AS late_stock, (l.avg_stock-e.avg_stock) AS stock_change, (l.avg_stock-e.avg_stock)*1.0/NULLIF(e.avg_stock,0) AS stock_change_pct FROM period_item e JOIN period_item l ON e.item_cd=l.item_cd AND e.on_item_no=l.on_item_no AND e.period=''early'' AND l.period=''late'') SELECT * FROM wide ORDER BY stock_change DESC LIMIT 30;"}]}]}]'),
  ('49154967-b8bc-5a86-acfe-81c6e2ece9eb', '6c8eb00a-f68f-5306-9d35-ae99f729e52b', '2f650d3c-4523-52eb-bebe-df742a1bc4cf', 'usr-slack-velen', 'EMART24의 active schedule target 샘플에서는 `interval_minutes = 1440`이고 `last_enqueued_at`이 비어 있는 대상이 관측되어, 현재 주기와 enqueue 상태가 변화율에 맞게 설계되어 있는지 점검할 여지가 있습니다 [4]. 다만 이는 샘플 관측이므로 전체 EMART24 target에 그대로 일반화하지 않고, cadence 검증의 출발점으로만 사용하는 것이 적절합니다 [4].  Store-level hotspot도 함께 분리해 볼 수 있습니다. 반복 스캔 기준으로 OLIVEYOUNG 명동거리점은 *5회 스캔, N=24,141건 중 11,698건 변화, 48.46%*, OLIVEYOUNG 명동타임워크점은 *6회 스캔, N=34,108건 중 9,429건 변화, 27.64%*, CU 연수시영승기점은 **2회 스캔, N=8,330건 중 8,330건 변화, 100.00%**로 관측됐습니다 [5]. 따라서 전면 확대보다는 EMART24 brand 후보와 hotspot store 후보를 나눠 제한적으로 검증하는 방식이 안전합니다 [5].  권장 액션  1. 운영/데이터팀은 EMART24를 제한적 monitoring cadence 실험군으로 지정 - store_inventory_schedule_targets에서 EMART24 active target의 interval_minutes, last_enqueued_at, enqueue 성공 여부를 먼저 확인하고, 일부 대상에 한해 현행 주기 대비 더 짧은 주기를 테스트합니다 [4]. 1. 분석팀은 EMART24 + hotspot store의 before-after 지표를 별도 대시보드로 비교 - 실험 전후로 store_inventory_runs, store_scan_logs의 successful runs, scanned items, changed_count, failure 비율을 같은 UTC 기준으로 추적해 “더 자주 봤을 때 변화 포착이 실제로 늘어나는지”를 검증합니다 [1] [5]. 1. 플랫폼팀은 rollout 전 데이터 품질 조건을 게이트로 설정 - failures / D1 size errors, running rows with nonzero summaries가 coverage와 지표 산정에 영향을 줄 수 있으므로, 실험 결과에는 성공 스캔만 포함하고 running/failure row는 분리 검토해야 합니다 [2] [3].  판단  이번 결과는 매출 개선 주장이 아니라, *EMART24의 모니터링 주기를 제한적으로 조정해 변화 감지 효율을 검증할 기회*입니다. 관측 창이 *2026-05-29 04:32 ~ 16:10 UTC*로 짧고, failures / D1 size errors와 running row 이슈가 함께 확인되므로 전면 rollout보다는 *EMART24 + hotspot store 대상의 limited cadence before-after validation*을 권장합니다 [1] [2] [3].', '2026-06-16T10:00:13.521Z', '2026-06-16T10:00:13.521Z', '[{"type": "section", "block_id": "VONQ8", "text": {"type": "mrkdwn", "text": "EMART24의 active schedule target 샘플에서는 `interval_minutes = 1440`이고 `last_enqueued_at`이 비어 있는 대상이 관측되어, 현재 주기와 enqueue 상태가 변화율에 맞게 설계되어 있는지 점검할 여지가 있습니다 [4]. 다만 이는 샘플 관측이므로 전체 EMART24 target에 그대로 일반화하지 않고, cadence 검증의 출발점으로만 사용하는 것이 적절합니다 [4].", "verbatim": false}}, {"type": "section", "block_id": "TkQ1i", "text": {"type": "mrkdwn", "text": "Store-level hotspot도 함께 분리해 볼 수 있습니다. 반복 스캔 기준으로 OLIVEYOUNG 명동거리점은 *5회 스캔, N=24,141건 중 11,698건 변화, 48.46%*, OLIVEYOUNG 명동타임워크점은 *6회 스캔, N=34,108건 중 9,429건 변화, 27.64%*, CU 연수시영승기점은 **2회 스캔, N=8,330건 중 8,330건 변화, 100.00%**로 관측됐습니다 [5]. 따라서 전면 확대보다는 EMART24 brand 후보와 hotspot store 후보를 나눠 제한적으로 검증하는 방식이 안전합니다 [5].", "verbatim": false}}, {"type": "header", "block_id": "/0kbR", "text": {"type": "plain_text", "text": "권장 액션", "emoji": true}}, {"type": "rich_text", "block_id": "+6HSQ", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "운영/데이터팀은 EMART24를 제한적 monitoring cadence 실험군으로 지정", "style": {"bold": true}}]}], "style": "ordered", "indent": 0}, {"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "store_inventory_schedule_targets", "style": {"code": true}}, {"type": "text", "text": "에서 EMART24 active target의 "}, {"type": "text", "text": "interval_minutes", "style": {"code": true}}, {"type": "text", "text": ", "}, {"type": "text", "text": "last_enqueued_at", "style": {"code": true}}, {"type": "text", "text": ", enqueue 성공 여부를 먼저 확인하고, 일부 대상에 한해 현행 주기 대비 더 짧은 주기를 테스트합니다 [4]."}]}], "style": "bullet", "indent": 1}, {"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "분석팀은 EMART24 + hotspot store의 before-after 지표를 별도 대시보드로 비교", "style": {"bold": true}}]}], "style": "ordered", "indent": 0}, {"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "실험 전후로 "}, {"type": "text", "text": "store_inventory_runs", "style": {"code": true}}, {"type": "text", "text": ", "}, {"type": "text", "text": "store_scan_logs", "style": {"code": true}}, {"type": "text", "text": "의 successful runs, scanned items, changed_count, failure 비율을 같은 UTC 기준으로 추적해 “더 자주 봤을 때 변화 포착이 실제로 늘어나는지”를 검증합니다 [1] [5]."}]}], "style": "bullet", "indent": 1}, {"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "플랫폼팀은 rollout 전 데이터 품질 조건을 게이트로 설정", "style": {"bold": true}}]}], "style": "ordered", "indent": 0}, {"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "failures / D1 size errors, running rows with nonzero summaries가 coverage와 지표 산정에 영향을 줄 수 있으므로, 실험 결과에는 성공 스캔만 포함하고 running/failure row는 분리 검토해야 합니다 [2] [3]."}]}], "style": "bullet", "indent": 1}]}, {"type": "header", "block_id": "YIt1m", "text": {"type": "plain_text", "text": "판단", "emoji": true}}, {"type": "section", "block_id": "4bD9L", "text": {"type": "mrkdwn", "text": "이번 결과는 매출 개선 주장이 아니라, *EMART24의 모니터링 주기를 제한적으로 조정해 변화 감지 효율을 검증할 기회*입니다. 관측 창이 *2026-05-29 04:32 ~ 16:10 UTC*로 짧고, failures / D1 size errors와 running row 이슈가 함께 확인되므로 전면 rollout보다는 *EMART24 + hotspot store 대상의 limited cadence before-after validation*을 권장합니다 [1] [2] [3].", "verbatim": false}}]')
on conflict (id) do nothing;

insert into briar_channel_messages (id, channel_id, parent_message_id, author_user_id, body, created_at, updated_at, blocks_json)
values
  ('8350cb71-9902-542c-b990-e6e8338f61d2', '6c8eb00a-f68f-5306-9d35-ae99f729e52b', '2f650d3c-4523-52eb-bebe-df742a1bc4cf', 'usr-slack-velen', 'Evidence  *[1]*  - Rows: 4 - Executed at (UTC): 2026-06-16T08:55:19.370Z  SELECT r.brand, COUNT(*) AS success_runs, COUNT(DISTINCT r.store_cd) AS stores, SUM(l.item_count) AS scanned_items, SUM(l.changed_count) AS changed_items, ROUND(100.0*SUM(l.changed_count)/NULLIF(SUM(l.item_count),0),2) AS change_rate_pct, AVG(l.changed_count) AS avg_changed_per_run, MIN(r.started_at) AS min_started_at, MAX(r.started_at) AS max_started_at FROM store_inventory_runs r JOIN store_scan_logs l ON l.run_id=r.id WHERE r.id &gt;= 400000 AND l.status=''success'' AND l.item_count&gt;0 GROUP BY r.brand ORDER BY changed_items DESC;  *[2]*  - Rows: 10 - Executed at (UTC): 2026-06-16T08:54:54.900Z  SELECT * FROM store_scan_logs ORDER BY run_id DESC LIMIT 10;  *[3]*  - Rows: 50 - Executed at (UTC): 2026-06-16T08:55:04.215Z  SELECT r.id,r.brand,r.store_cd,r.store_name,r.started_at,r.finished_at,r.status,r.item_count,s.total_items,s.in_stock_items,s.zero_stock_items,s.total_units,s.max_stock FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE s.total_items&gt;0 ORDER BY r.id DESC LIMIT 50;  *[4]*  - Rows: 50 - Executed at (UTC): 2026-06-16T08:55:04.215Z  SELECT brand, store_cd, store_name, active, status, interval_minutes, last_enqueued_at FROM store_inventory_schedule_targets ORDER BY updated_at DESC LIMIT 50;  *[5]*  - Rows: 20 - Executed at (UTC): 2026-06-16T08:55:19.370Z  SELECT r.brand, r.store_cd, r.store_name, COUNT(*) AS success_runs, SUM(l.item_count) AS scanned_items, SUM(l.changed_count) AS changed_items, ROUND(100.0*SUM(l.changed_count)/NULLIF(SUM(l.item_count),0),2) AS change_rate_pct, AVG(l.changed_count) AS avg_changed_per_run, MAX(r.started_at) AS last_started_at FROM store_inventory_runs r JOIN store_scan_logs l ON l.run_id=r.id WHERE r.id &gt;= 400000 AND l.status=''success'' AND l.item_count&gt;0 GROUP BY r.brand, r.store_cd, r.store_name HAVING success_runs&gt;=2 ORDER BY changed_items DESC LIMIT 20;', '2026-06-16T10:00:13.788Z', '2026-06-16T10:00:13.788Z', '[{"type": "header", "block_id": "tlChq", "text": {"type": "plain_text", "text": "Evidence", "emoji": true}}, {"type": "section", "block_id": "LR1n3", "text": {"type": "mrkdwn", "text": "*[1]*", "verbatim": false}}, {"type": "rich_text", "block_id": "2adOI", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 4"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-16T08"}, {"type": "emoji", "name": "55"}, {"type": "text", "text": "19.370Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "nFXqF", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "SELECT r.brand, COUNT(*) AS success_runs, COUNT(DISTINCT r.store_cd) AS stores, SUM(l.item_count) AS scanned_items, SUM(l.changed_count) AS changed_items, ROUND(100.0*SUM(l.changed_count)/NULLIF(SUM(l.item_count),0),2) AS change_rate_pct, AVG(l.changed_count) AS avg_changed_per_run, MIN(r.started_at) AS min_started_at, MAX(r.started_at) AS max_started_at FROM store_inventory_runs r JOIN store_scan_logs l ON l.run_id=r.id WHERE r.id >= 400000 AND l.status=''success'' AND l.item_count>0 GROUP BY r.brand ORDER BY changed_items DESC;"}]}]}, {"type": "section", "block_id": "6vzRa", "text": {"type": "mrkdwn", "text": "*[2]*", "verbatim": false}}, {"type": "rich_text", "block_id": "cG6F+", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 10"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-16T08"}, {"type": "emoji", "name": "54"}, {"type": "text", "text": "54.900Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "EKsCq", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "SELECT * FROM store_scan_logs ORDER BY run_id DESC LIMIT 10;"}]}]}, {"type": "section", "block_id": "dLTG/", "text": {"type": "mrkdwn", "text": "*[3]*", "verbatim": false}}, {"type": "rich_text", "block_id": "AL5J4", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 50"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-16T08"}, {"type": "emoji", "name": "55"}, {"type": "text", "text": "04.215Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "6hH82", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "SELECT r.id,r.brand,r.store_cd,r.store_name,r.started_at,r.finished_at,r.status,r.item_count,s.total_items,s.in_stock_items,s.zero_stock_items,s.total_units,s.max_stock FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE s.total_items>0 ORDER BY r.id DESC LIMIT 50;"}]}]}, {"type": "section", "block_id": "kgXFN", "text": {"type": "mrkdwn", "text": "*[4]*", "verbatim": false}}, {"type": "rich_text", "block_id": "JPw0W", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 50"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-16T08"}, {"type": "emoji", "name": "55"}, {"type": "text", "text": "04.215Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "E4+IU", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "SELECT brand, store_cd, store_name, active, status, interval_minutes, last_enqueued_at FROM store_inventory_schedule_targets ORDER BY updated_at DESC LIMIT 50;"}]}]}, {"type": "section", "block_id": "o+Ko7", "text": {"type": "mrkdwn", "text": "*[5]*", "verbatim": false}}, {"type": "rich_text", "block_id": "PNXi7", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 20"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-16T08"}, {"type": "emoji", "name": "55"}, {"type": "text", "text": "19.370Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "p6BRD", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "SELECT r.brand, r.store_cd, r.store_name, COUNT(*) AS success_runs, SUM(l.item_count) AS scanned_items, SUM(l.changed_count) AS changed_items, ROUND(100.0*SUM(l.changed_count)/NULLIF(SUM(l.item_count),0),2) AS change_rate_pct, AVG(l.changed_count) AS avg_changed_per_run, MAX(r.started_at) AS last_started_at FROM store_inventory_runs r JOIN store_scan_logs l ON l.run_id=r.id WHERE r.id >= 400000 AND l.status=''success'' AND l.item_count>0 GROUP BY r.brand, r.store_cd, r.store_name HAVING success_runs>=2 ORDER BY changed_items DESC LIMIT 20;"}]}]}]'),
  ('6780a710-2649-5106-905c-50b1d68db29d', '6c8eb00a-f68f-5306-9d35-ae99f729e52b', 'dfc59542-c9cc-5fce-b739-84afe8df90b1', 'usr-slack-velen', '최근 48시간 기준: *2026-06-15 04:32:00 ~ 2026-06-17 04:32:00 UTC*입니다.  이 기간의 `store_scan_logs`에는 *전체 스캔 로그가 0건*이었고, 따라서 *브랜드별 성공 스캔수도 집계된 브랜드가 없습니다(0건)*. [QID: 1] [QID: 2]  참고로 이 테이블의 최신 스캔 로그 시각은 *2026-05-29 17:17:44.925 UTC*라서, 현재 기준 최근 48시간 안에는 데이터가 없습니다. [QID: 3]  브랜드 | 성공 스캔수 없음 | 0', '2026-06-17T04:33:17.853Z', '2026-06-17T04:33:17.853Z', '[{"type": "section", "block_id": "sTgyB", "text": {"type": "mrkdwn", "text": "최근 48시간 기준: *2026-06-15 04:32:00 ~ 2026-06-17 04:32:00 UTC*입니다.", "verbatim": false}}, {"type": "section", "block_id": "7vsU8", "text": {"type": "mrkdwn", "text": "이 기간의 `store_scan_logs`에는 *전체 스캔 로그가 0건*이었고, 따라서 *브랜드별 성공 스캔수도 집계된 브랜드가 없습니다(0건)*. [QID: 1] [QID: 2]", "verbatim": false}}, {"type": "section", "block_id": "DidAr", "text": {"type": "mrkdwn", "text": "참고로 이 테이블의 최신 스캔 로그 시각은 *2026-05-29 17:17:44.925 UTC*라서, 현재 기준 최근 48시간 안에는 데이터가 없습니다. [QID: 3]", "verbatim": false}}]')
