values
  ('0ac5e5ea-dea7-5704-a8a1-ba4938a047df', '6c8eb00a-f68f-5306-9d35-ae99f729e52b', '1fa46546-00d8-543f-8ae8-d6a5379067a3', 'usr-slack-velen', 'Evidence  *[1]*  - Rows: 1 - Executed at (UTC): 2026-06-21T07:10:48.900Z  WITH latest AS (SELECT s.brand,s.store_cd,substr(r.started_at,1,10) AS date_utc,MAX(s.run_id) AS run_id FROM store_inventory_run_summaries s JOIN store_inventory_runs r ON r.id=s.run_id WHERE r.status=''success'' AND s.brand=''CU'' AND substr(r.started_at,1,10) IN (''2026-05-28'',''2026-05-29'') GROUP BY 1,2,3), daily AS (SELECT l.date_utc,l.store_cd,s.total_items,s.in_stock_items,s.zero_stock_items,s.total_units FROM latest l JOIN store_inventory_run_summaries s ON s.run_id=l.run_id), pivot AS (SELECT a.store_cd, a.total_items AS items_0528, a.in_stock_items AS in_stock_0528, a.zero_stock_items AS zero_0528, a.total_units AS units_0528, b.total_items AS items_0529, b.in_stock_items AS in_stock_0529, b.zero_stock_items AS zero_0529, b.total_units AS units_0529 FROM daily a JOIN daily b ON a.store_cd=b.store_cd AND a.date_utc=''2026-05-28'' AND b.date_utc=''2026-05-29'') SELECT COUNT(*) AS same_stores, SUM(units_0528) AS units_0528, SUM(units_0529) AS units_0529, SUM(units_0529)-SUM(units_0528) AS unit_change, ROUND(100.0*(SUM(units_0529)-SUM(units_0528))/NULLIF(SUM(units_0528),0),2) AS unit_change_pct, SUM(zero_0528) AS zero_0528, SUM(zero_0529) AS zero_0529, ROUND(100.0*SUM(zero_0528)/SUM(items_0528),2) AS zero_rate_0528_pct, ROUND(100.0*SUM(zero_0529)/SUM(items_0529),2) AS zero_rate_0529_pct FROM pivot;  *[2]*  - Rows: 1 - Executed at (UTC): 2026-06-21T07:11:20.019Z  WITH latest AS (SELECT s.brand,s.store_cd,substr(r.started_at,1,10) AS date_utc,MAX(s.run_id) AS run_id FROM store_inventory_run_summaries s JOIN store_inventory_runs r ON r.id=s.run_id WHERE r.status=''success'' AND s.brand=''CU'' AND substr(r.started_at,1,10) IN (''2026-05-28'',''2026-05-29'') GROUP BY 1,2,3), daily AS (SELECT l.date_utc,l.store_cd,s.total_items,s.in_stock_items,s.zero_stock_items,s.total_units FROM latest l JOIN store_inventory_run_summaries s ON s.run_id=l.run_id), pivot AS (SELECT a.store_cd, a.total_items AS items_0528, a.in_stock_items AS in_stock_0528, a.zero_stock_items AS zero_0528, a.total_units AS units_0528, b.total_items AS items_0529, b.in_stock_items AS in_stock_0529, b.zero_stock_items AS zero_0529, b.total_units AS units_0529 FROM daily a JOIN daily b ON a.store_cd=b.store_cd AND a.date_utc=''2026-05-28'' AND b.date_utc=''2026-05-29'') SELECT COUNT(*) AS stores, SUM(CASE WHEN units_0529-units_0528 &gt;= 1000 THEN 1 ELSE 0 END) AS stores_up_1000_units, SUM(CASE WHEN units_0529-units_0528 &lt;= -1000 THEN 1 ELSE 0 END) AS stores_down_1000_units, SUM(CASE WHEN units_0529-units_0528 &gt;= 1000 THEN units_0529-units_0528 ELSE 0 END) AS total_positive_change_ge_1000, SUM(CASE WHEN units_0529-units_0528 &lt;= -1000 THEN units_0529-units_0528 ELSE 0 END) AS total_negative_change_le_minus_1000 FROM pivot WHERE items_0529&gt;=2000 AND units_0528&gt;0;  *[3]*  - Rows: 20 - Executed at (UTC): 2026-06-21T07:10:48.900Z  WITH latest AS (SELECT s.brand,s.store_cd,substr(r.started_at,1,10) AS date_utc,MAX(s.run_id) AS run_id FROM store_inventory_run_summaries s JOIN store_inventory_runs r ON r.id=s.run_id WHERE r.status=''success'' AND s.brand=''CU'' AND substr(r.started_at,1,10) IN (''2026-05-28'',''2026-05-29'') GROUP BY 1,2,3), daily AS (SELECT l.date_utc,l.store_cd,s.total_items,s.in_stock_items,s.zero_stock_items,s.total_units FROM latest l JOIN store_inventory_run_summaries s ON s.run_id=l.run_id), pivot AS (SELECT a.store_cd, a.total_items AS items_0528, a.in_stock_items AS in_stock_0528, a.zero_stock_items AS zero_0528, a.total_units AS units_0528, b.total_items AS items_0529, b.in_stock_items AS in_stock_0529, b.zero_stock_items AS zero_0529, b.total_units AS units_0529 FROM daily a JOIN daily b ON a.store_cd=b.store_cd AND a.date_utc=''2026-05-28'' AND b.date_utc=''2026-05-29'') SELECT p.store_cd, r.store_name, items_0529, units_0528, units_0529, units_0529-units_0528 AS unit_change, ROUND(100.0*(units_0529-units_0528)/NULLIF(units_0528,0),1) AS unit_change_pct, ROUND(100.0*zero_0529/items_0529,1) AS zero_rate_0529', '2026-06-21T10:00:13.163Z', '2026-06-21T10:00:13.163Z', '[{"type": "header", "block_id": "7P2Sr", "text": {"type": "plain_text", "text": "Evidence", "emoji": true}}, {"type": "section", "block_id": "CNZeE", "text": {"type": "mrkdwn", "text": "*[1]*", "verbatim": false}}, {"type": "rich_text", "block_id": "RaLDb", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 1"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-21T07"}, {"type": "emoji", "name": "10"}, {"type": "text", "text": "48.900Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "vreNe", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "WITH latest AS (SELECT s.brand,s.store_cd,substr(r.started_at,1,10) AS date_utc,MAX(s.run_id) AS run_id FROM store_inventory_run_summaries s JOIN store_inventory_runs r ON r.id=s.run_id WHERE r.status=''success'' AND s.brand=''CU'' AND substr(r.started_at,1,10) IN (''2026-05-28'',''2026-05-29'') GROUP BY 1,2,3), daily AS (SELECT l.date_utc,l.store_cd,s.total_items,s.in_stock_items,s.zero_stock_items,s.total_units FROM latest l JOIN store_inventory_run_summaries s ON s.run_id=l.run_id), pivot AS (SELECT a.store_cd, a.total_items AS items_0528, a.in_stock_items AS in_stock_0528, a.zero_stock_items AS zero_0528, a.total_units AS units_0528, b.total_items AS items_0529, b.in_stock_items AS in_stock_0529, b.zero_stock_items AS zero_0529, b.total_units AS units_0529 FROM daily a JOIN daily b ON a.store_cd=b.store_cd AND a.date_utc=''2026-05-28'' AND b.date_utc=''2026-05-29'') SELECT COUNT(*) AS same_stores, SUM(units_0528) AS units_0528, SUM(units_0529) AS units_0529, SUM(units_0529)-SUM(units_0528) AS unit_change, ROUND(100.0*(SUM(units_0529)-SUM(units_0528))/NULLIF(SUM(units_0528),0),2) AS unit_change_pct, SUM(zero_0528) AS zero_0528, SUM(zero_0529) AS zero_0529, ROUND(100.0*SUM(zero_0528)/SUM(items_0528),2) AS zero_rate_0528_pct, ROUND(100.0*SUM(zero_0529)/SUM(items_0529),2) AS zero_rate_0529_pct FROM pivot;"}]}]}, {"type": "section", "block_id": "2yqKW", "text": {"type": "mrkdwn", "text": "*[2]*", "verbatim": false}}, {"type": "rich_text", "block_id": "T83es", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 1"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-21T07"}, {"type": "emoji", "name": "11"}, {"type": "text", "text": "20.019Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "++wXu", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "WITH latest AS (SELECT s.brand,s.store_cd,substr(r.started_at,1,10) AS date_utc,MAX(s.run_id) AS run_id FROM store_inventory_run_summaries s JOIN store_inventory_runs r ON r.id=s.run_id WHERE r.status=''success'' AND s.brand=''CU'' AND substr(r.started_at,1,10) IN (''2026-05-28'',''2026-05-29'') GROUP BY 1,2,3), daily AS (SELECT l.date_utc,l.store_cd,s.total_items,s.in_stock_items,s.zero_stock_items,s.total_units FROM latest l JOIN store_inventory_run_summaries s ON s.run_id=l.run_id), pivot AS (SELECT a.store_cd, a.total_items AS items_0528, a.in_stock_items AS in_stock_0528, a.zero_stock_items AS zero_0528, a.total_units AS units_0528, b.total_items AS items_0529, b.in_stock_items AS in_stock_0529, b.zero_stock_items AS zero_0529, b.total_units AS units_0529 FROM daily a JOIN daily b ON a.store_cd=b.store_cd AND a.date_utc=''2026-05-28'' AND b.date_utc=''2026-05-29'') SELECT COUNT(*) AS stores, SUM(CASE WHEN units_0529-units_0528 >= 1000 THEN 1 ELSE 0 END) AS stores_up_1000_units, SUM(CASE WHEN units_0529-units_0528 <= -1000 THEN 1 ELSE 0 END) AS stores_down_1000_units, SUM(CASE WHEN units_0529-units_0528 >= 1000 THEN units_0529-units_0528 ELSE 0 END) AS total_positive_change_ge_1000, SUM(CASE WHEN units_0529-units_0528 <= -1000 THEN units_0529-units_0528 ELSE 0 END) AS total_negative_change_le_minus_1000 FROM pivot WHERE items_0529>=2000 AND units_0528>0;"}]}]}, {"type": "section", "block_id": "wPecg", "text": {"type": "mrkdwn", "text": "*[3]*", "verbatim": false}}, {"type": "rich_text", "block_id": "0+PZY", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 20"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-21T07"}, {"type": "emoji", "name": "10"}, {"type": "text", "text": "48.900Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "avC75", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "WITH latest AS (SELECT s.brand,s.store_cd,substr(r.started_at,1,10) AS date_utc,MAX(s.run_id) AS run_id FROM store_inventory_run_summaries s JOIN store_inventory_runs r ON r.id=s.run_id WHERE r.status=''success'' AND s.brand=''CU'' AND substr(r.started_at,1,10) IN (''2026-05-28'',''2026-05-29'') GROUP BY 1,2,3), daily AS (SELECT l.date_utc,l.store_cd,s.total_items,s.in_stock_items,s.zero_stock_items,s.total_units FROM latest l JOIN store_inventory_run_summaries s ON s.run_id=l.run_id), pivot AS (SELECT a.store_cd, a.total_items AS items_0528, a.in_stock_items AS in_stock_0528, a.zero_stock_items AS zero_0528, a.total_units AS units_0528, b.total_items AS items_0529, b.in_stock_items AS in_stock_0529, b.zero_stock_items AS zero_0529, b.total_units AS units_0529 FROM daily a JOIN daily b ON a.store_cd=b.store_cd AND a.date_utc=''2026-05-28'' AND b.date_utc=''2026-05-29'') SELECT p.store_cd, r.store_name, items_0529, units_0528, units_0529, units_0529-units_0528 AS unit_change, ROUND(100.0*(units_0529-units_0528)/NULLIF(units_0528,0),1) AS unit_change_pct, ROUND(100.0*zero_0529/items_0529,1) AS zero_rate_0529_pct FROM pivot p LEFT JOIN store_inventory_runs r ON r.id=(SELECT MAX(r2.id) FROM store_inventory_runs r2 WHERE r2.brand=''CU'' AND r2.store_cd=p.store_cd AND substr(r2.started_at,1,10)=''2026-05-29'' AND r2.status=''success'') WHERE items_0529>=2000 AND units_0528>0 ORDER BY unit_change DESC LIMIT 20;"}]}]}]'),
  ('ccb36f1f-2baf-5754-a197-d7714bfeea12', '9e166354-280f-5f22-8881-6d0f4afb255d', '9cc15002-6dc5-5f80-b67b-f3001c749df5', 'usr-slack-noh-hee-young', '방금 DB로 확인하려 했는데 CU 재고 로그 쿼리가 타임아웃이라 “최근 변경”을 확정해 말하긴 어렵습니다. 한다면 한다—먼저 조회 범위를 특정해야 해요: 전체 CU인가요, 특정 점포/상품인가요?  레퍼런스: <https://velen.wordbricks.ai/cvs/chat/01KVQ0N9J81FVX2XZMJQ3J07BG|Velen에서 보기>', '2026-06-22T06:38:31.649Z', '2026-06-22T06:38:31.649Z', '[{"type": "section", "block_id": "DT/6J", "text": {"type": "mrkdwn", "text": "방금 DB로 확인하려 했는데 CU 재고 로그 쿼리가 타임아웃이라 “최근 변경”을 확정해 말하긴 어렵습니다. 한다면 한다—먼저 조회 범위를 특정해야 해요: 전체 CU인가요, 특정 점포/상품인가요?", "verbatim": false}}, {"type": "section", "block_id": "kQVWQ", "text": {"type": "mrkdwn", "text": "레퍼런스: <https://velen.wordbricks.ai/cvs/chat/01KVQ0N9J81FVX2XZMJQ3J07BG|Velen에서 보기>", "verbatim": false}}]'),
