values
  ('977146a7-3dfd-5084-a84a-b2cf4678e759', '6c8eb00a-f68f-5306-9d35-ae99f729e52b', 'ede0545e-b0ad-5f89-a0eb-9f26dc16d06f', 'usr-slack-velen', 'Evidence  *[1]*  - Rows: 15 - Executed at (UTC): 2026-06-22T07:15:59.713Z  SELECT r.brand AS brand, date(r.started_at) AS day, COUNT(*) AS runs, COUNT(DISTINCT r.store_cd) AS stores, ROUND(100.0*SUM(s.in_stock_items)/NULLIF(SUM(s.total_items),0),2) AS in_stock_item_rate_pct, SUM(s.total_items) AS total_items_observed, SUM(s.in_stock_items) AS in_stock_items_observed, SUM(s.zero_stock_items) AS zero_stock_items_observed FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.status=''success'' AND r.started_at &gt;= ''2026-05-27'' GROUP BY r.brand, date(r.started_at) ORDER BY brand, day LIMIT 100;  *[2]*  - Rows: 30 - Executed at (UTC): 2026-06-22T07:15:59.713Z  SELECT r.store_cd, r.store_name, date(r.started_at) AS day, COUNT(*) AS runs, ROUND(AVG(s.total_items),1) AS avg_items, ROUND(AVG(s.in_stock_items),1) AS avg_in_stock, ROUND(100.0*SUM(s.in_stock_items)/NULLIF(SUM(s.total_items),0),2) AS in_stock_rate_pct, ROUND(AVG(s.total_units),1) AS avg_units FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.status=''success'' AND r.brand=''TOUSLESJOURS'' AND r.started_at &gt;= ''2026-05-27'' GROUP BY r.store_cd, r.store_name, date(r.started_at) ORDER BY r.store_cd, day LIMIT 100;  *[3]*  - Rows: 10 - Executed at (UTC): 2026-06-22T07:16:16.152Z  WITH daily AS (SELECT r.store_cd, r.store_name, date(r.started_at) AS day, SUM(s.total_items) AS total_items, SUM(s.in_stock_items) AS in_stock_items, ROUND(100.0*SUM(s.in_stock_items)/NULLIF(SUM(s.total_items),0),2) AS rate FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.status=''success'' AND r.brand=''TOUSLESJOURS'' AND r.started_at &gt;= ''2026-05-27'' GROUP BY r.store_cd, r.store_name, date(r.started_at)), pivot AS (SELECT store_cd, store_name, MAX(CASE WHEN day=''2026-05-27'' THEN rate END) AS rate_0527, MAX(CASE WHEN day=''2026-05-28'' THEN rate END) AS rate_0528, MAX(CASE WHEN day=''2026-05-29'' THEN rate END) AS rate_0529, MAX(CASE WHEN day=''2026-05-27'' THEN total_items END) AS total_0527, MAX(CASE WHEN day=''2026-05-29'' THEN total_items END) AS total_0529, MAX(CASE WHEN day=''2026-05-27'' THEN in_stock_items END) AS instock_0527, MAX(CASE WHEN day=''2026-05-29'' THEN in_stock_items END) AS instock_0529 FROM daily GROUP BY store_cd, store_name) SELECT store_cd, store_name, rate_0527, rate_0528, rate_0529, ROUND(rate_0529-rate_0527,2) AS rate_change_pp, total_0527, total_0529, instock_0527, instock_0529, instock_0529-instock_0527 AS instock_observation_change FROM pivot WHERE rate_0527 IS NOT NULL AND rate_0529 IS NOT NULL ORDER BY rate_change_pp DESC LIMIT 20;', '2026-06-22T10:00:16.491Z', '2026-06-22T10:00:16.491Z', '[{"type": "header", "block_id": "z36dB", "text": {"type": "plain_text", "text": "Evidence", "emoji": true}}, {"type": "section", "block_id": "bGCbD", "text": {"type": "mrkdwn", "text": "*[1]*", "verbatim": false}}, {"type": "rich_text", "block_id": "7KAWB", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 15"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-22T07"}, {"type": "emoji", "name": "15"}, {"type": "text", "text": "59.713Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "YfzlI", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "SELECT r.brand AS brand, date(r.started_at) AS day, COUNT(*) AS runs, COUNT(DISTINCT r.store_cd) AS stores, ROUND(100.0*SUM(s.in_stock_items)/NULLIF(SUM(s.total_items),0),2) AS in_stock_item_rate_pct, SUM(s.total_items) AS total_items_observed, SUM(s.in_stock_items) AS in_stock_items_observed, SUM(s.zero_stock_items) AS zero_stock_items_observed FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.status=''success'' AND r.started_at >= ''2026-05-27'' GROUP BY r.brand, date(r.started_at) ORDER BY brand, day LIMIT 100;"}]}]}, {"type": "section", "block_id": "kkm1o", "text": {"type": "mrkdwn", "text": "*[2]*", "verbatim": false}}, {"type": "rich_text", "block_id": "C0owF", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 30"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-22T07"}, {"type": "emoji", "name": "15"}, {"type": "text", "text": "59.713Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "hlyBu", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "SELECT r.store_cd, r.store_name, date(r.started_at) AS day, COUNT(*) AS runs, ROUND(AVG(s.total_items),1) AS avg_items, ROUND(AVG(s.in_stock_items),1) AS avg_in_stock, ROUND(100.0*SUM(s.in_stock_items)/NULLIF(SUM(s.total_items),0),2) AS in_stock_rate_pct, ROUND(AVG(s.total_units),1) AS avg_units FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.status=''success'' AND r.brand=''TOUSLESJOURS'' AND r.started_at >= ''2026-05-27'' GROUP BY r.store_cd, r.store_name, date(r.started_at) ORDER BY r.store_cd, day LIMIT 100;"}]}]}, {"type": "section", "block_id": "4KprL", "text": {"type": "mrkdwn", "text": "*[3]*", "verbatim": false}}, {"type": "rich_text", "block_id": "CuEzW", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 10"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-22T07"}, {"type": "emoji", "name": "16"}, {"type": "text", "text": "16.152Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "RKYa4", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "WITH daily AS (SELECT r.store_cd, r.store_name, date(r.started_at) AS day, SUM(s.total_items) AS total_items, SUM(s.in_stock_items) AS in_stock_items, ROUND(100.0*SUM(s.in_stock_items)/NULLIF(SUM(s.total_items),0),2) AS rate FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.status=''success'' AND r.brand=''TOUSLESJOURS'' AND r.started_at >= ''2026-05-27'' GROUP BY r.store_cd, r.store_name, date(r.started_at)), pivot AS (SELECT store_cd, store_name, MAX(CASE WHEN day=''2026-05-27'' THEN rate END) AS rate_0527, MAX(CASE WHEN day=''2026-05-28'' THEN rate END) AS rate_0528, MAX(CASE WHEN day=''2026-05-29'' THEN rate END) AS rate_0529, MAX(CASE WHEN day=''2026-05-27'' THEN total_items END) AS total_0527, MAX(CASE WHEN day=''2026-05-29'' THEN total_items END) AS total_0529, MAX(CASE WHEN day=''2026-05-27'' THEN in_stock_items END) AS instock_0527, MAX(CASE WHEN day=''2026-05-29'' THEN in_stock_items END) AS instock_0529 FROM daily GROUP BY store_cd, store_name) SELECT store_cd, store_name, rate_0527, rate_0528, rate_0529, ROUND(rate_0529-rate_0527,2) AS rate_change_pp, total_0527, total_0529, instock_0527, instock_0529, instock_0529-instock_0527 AS instock_observation_change FROM pivot WHERE rate_0527 IS NOT NULL AND rate_0529 IS NOT NULL ORDER BY rate_change_pp DESC LIMIT 20;"}]}]}]'),
  ('784e6bde-b7f6-5c0a-9d12-6425cb34c2bd', '9e166354-280f-5f22-8881-6d0f4afb255d', 'ed163520-f0b3-5d3c-948f-5c5a1644d9ee', 'usr-slack-noh-hee-young', '지금 확인해보니 CU 재고 변경을 보려는 핵심 테이블은 있는데, 전체 현황 집계 쿼리가 타임아웃 났어요. 매장명이나 상품명, “최근 24시간/7일”처럼 범위를 좁혀 주세요—재고는 보고서 말고 실제 스캔 데이터로 바로 잘라봐야 합니다.  레퍼런스: <https://velen.wordbricks.ai/cvs/chat/01KVQCQTK4C08W1CSGP158H6ZJ|Velen에서 보기>', '2026-06-22T10:09:49.027Z', '2026-06-22T10:09:49.027Z', '[{"type": "section", "block_id": "KmxWt", "text": {"type": "mrkdwn", "text": "지금 확인해보니 CU 재고 변경을 보려는 핵심 테이블은 있는데, 전체 현황 집계 쿼리가 타임아웃 났어요.\n매장명이나 상품명, “최근 24시간/7일”처럼 범위를 좁혀 주세요—재고는 보고서 말고 실제 스캔 데이터로 바로 잘라봐야 합니다.", "verbatim": false}}, {"type": "section", "block_id": "uAMM4", "text": {"type": "mrkdwn", "text": "레퍼런스: <https://velen.wordbricks.ai/cvs/chat/01KVQCQTK4C08W1CSGP158H6ZJ|Velen에서 보기>", "verbatim": false}}]'),
  ('a5301018-b822-554c-9327-4b2b0f7a0e42', '9e166354-280f-5f22-8881-6d0f4afb255d', 'ed163520-f0b3-5d3c-948f-5c5a1644d9ee', 'usr-slack-ian', '<@U0BA6CJBUUU> noh 타임아웃 난 sql 쿼리 알려줘', '2026-06-22T10:10:35.872Z', '2026-06-22T10:10:35.872Z', '[{"type": "rich_text", "block_id": "IUQzS", "elements": [{"type": "rich_text_section", "elements": [{"type": "user", "user_id": "U0BA6CJBUUU"}, {"type": "text", "text": " noh 타임아웃 난 sql 쿼리 알려줘"}]}]}]'),
  ('8abcca1d-5d1b-53b4-9d28-259f6fb61374', '9e166354-280f-5f22-8881-6d0f4afb255d', 'ed163520-f0b3-5d3c-948f-5c5a1644d9ee', 'usr-slack-noh-hee-young', '타임아웃 난 건 이 쿼리예요: `SELECT MAX(checked_at) AS latest_checked_at, COUNT(*) AS scan_logs FROM store_scan_logs WHERE brand=''CU'';`그다음 재시도한 `store_scan_logs ORDER BY run_id DESC LIMIT 1` + `inventory_latest_state COUNT` 묶음도 타임아웃 났습니다.', '2026-06-22T10:11:17.163Z', '2026-06-22T10:11:17.163Z', '[{"type": "section", "block_id": "fzq54", "text": {"type": "mrkdwn", "text": "타임아웃 난 건 이 쿼리예요: `SELECT MAX(checked_at) AS latest_checked_at, COUNT(*) AS scan_logs FROM store_scan_logs WHERE brand=''CU'';`그다음 재시도한 `store_scan_logs ORDER BY run_id DESC LIMIT 1` + `inventory_latest_state COUNT` 묶음도 타임아웃 났습니다.", "verbatim": false}}]'),
