  ('39ae3d33-926c-519c-a10a-15cb6fac64e5', 'a4f3887e-60b5-59f9-b4a2-8dd3f57ee239', '2887c8d4-c815-51f0-8a57-b77f512c1580', 'usr-slack-ian', '오잉', '2026-06-25T09:30:25.508Z', '2026-06-25T09:30:25.508Z', '[{"type": "rich_text", "block_id": "4gG19", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "오잉"}]}]}]'),
