  ('f4b148b4-de69-5784-aaf7-2d60b9073260', 'a4f3887e-60b5-59f9-b4a2-8dd3f57ee239', 'aec96b70-7644-5d7e-af6a-fa90a230cca4', 'usr-slack-sophia', '<@U0BA6CJBUUU> 응 93개를 제공해줘', '2026-06-26T12:25:30.102Z', '2026-06-26T12:25:30.102Z', '[{"type": "rich_text", "block_id": "rRfTA", "elements": [{"type": "rich_text_section", "elements": [{"type": "user", "user_id": "U0BA6CJBUUU"}, {"type": "text", "text": " 응 93개를 제공해줘"}]}]}]'),
