  ('13d5c1b7-84b5-5b56-94c5-952fbbce2ed6', 'a4f3887e-60b5-59f9-b4a2-8dd3f57ee239', 'e1f9ea3d-f336-5a21-908a-de3c006b9f5b', 'usr-slack-sophia', 'cu 데이터만 수백기가에요?? 벌써???', '2026-06-26T12:29:58.427Z', '2026-06-26T12:29:58.427Z', '[{"type": "rich_text", "block_id": "CwSp+", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "cu 데이터만 수백기가에요?? 벌써???"}]}]}]'),
