insert into briar_channel_messages (id, channel_id, parent_message_id, author_user_id, body, created_at, updated_at, blocks_json)
values
  ('4ad2123e-bdcc-519b-93ab-88e7abcae6b7', '6c8eb00a-f68f-5306-9d35-ae99f729e52b', '2124cb3d-a08b-5eff-8a8b-71209010ea45', 'usr-slack-velen', 'Evidence  *[1]*  - Rows: 5 - Executed at (UTC): 2026-06-11T07:45:51.101Z  WITH runs AS (SELECT r.brand, r.store_cd, r.store_name, r.started_at, s.total_units, LAG(s.total_units) OVER (PARTITION BY r.brand,r.store_cd ORDER BY r.started_at,r.id) prev_units FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.id &gt; 300000 AND r.status=''success'' AND r.brand IN (''CU'',''GS25'',''EMART24'',''OLIVEYOUNG'',''TOUSLESJOURS'')), diffs AS (SELECT brand, store_cd, total_units-prev_units AS delta FROM runs WHERE prev_units IS NOT NULL), agg AS (SELECT brand, COUNT(DISTINCT store_cd) AS stores_with_transitions, COUNT(*) AS transitions, SUM(CASE WHEN delta&gt;0 THEN delta ELSE 0 END) AS gross_increase_units, SUM(CASE WHEN delta&lt;0 THEN -delta ELSE 0 END) AS gross_decrease_units, SUM(ABS(delta)) AS gross_movement_units, SUM(delta) AS net_delta_units FROM diffs GROUP BY brand) SELECT brand, stores_with_transitions, transitions, gross_increase_units, gross_decrease_units, gross_movement_units, net_delta_units, ROUND(1.0*gross_movement_units/stores_with_transitions,1) AS movement_per_store, ROUND(1.0*gross_movement_units/transitions,1) AS movement_per_transition FROM agg ORDER BY gross_movement_units DESC;  *[2]*  - Rows: 2 - Executed at (UTC): 2026-06-11T07:47:18.485Z  WITH runs AS (SELECT r.store_cd, r.store_name, r.started_at, s.total_units, LAG(s.total_units) OVER (PARTITION BY r.store_cd ORDER BY r.started_at,r.id) prev_units FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.id &gt; 300000 AND r.status=''success'' AND r.brand=''OLIVEYOUNG''), diffs AS (SELECT CASE WHEN store_name LIKE ''%명동%'' THEN ''MYEONGDONG_NAME'' ELSE ''OTHER'' END AS segment, store_cd, total_units-prev_units AS delta FROM runs WHERE prev_units IS NOT NULL), agg AS (SELECT segment, COUNT(DISTINCT store_cd) AS stores, COUNT(*) AS transitions, SUM(CASE WHEN delta&gt;0 THEN delta ELSE 0 END) AS gross_increase_units, SUM(CASE WHEN delta&lt;0 THEN -delta ELSE 0 END) AS gross_decrease_units, SUM(ABS(delta)) AS gross_movement_units, SUM(delta) AS net_delta_units FROM diffs GROUP BY segment), total AS (SELECT SUM(gross_movement_units) total_movement FROM agg) SELECT segment, stores, transitions, gross_increase_units, gross_decrease_units, gross_movement_units, net_delta_units, ROUND(100.0*gross_movement_units/(SELECT total_movement FROM total),1) AS share_of_oliveyoung_movement_pct FROM agg ORDER BY gross_movement_units DESC;  *[3]*  - Rows: 1 - Executed at (UTC): 2026-06-11T07:46:32.334Z  WITH runs AS (SELECT r.brand, r.store_cd, r.store_name, r.started_at, s.total_units, LAG(s.total_units) OVER (PARTITION BY r.brand,r.store_cd ORDER BY r.started_at,r.id) prev_units FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.id &gt; 300000 AND r.status=''success'' AND r.brand=''OLIVEYOUNG''), diffs AS (SELECT store_cd, store_name, total_units-prev_units AS delta FROM runs WHERE prev_units IS NOT NULL), store_agg AS (SELECT store_cd, store_name, COUNT(*) AS transitions, SUM(CASE WHEN delta&gt;0 THEN delta ELSE 0 END) AS gross_increase_units, SUM(CASE WHEN delta&lt;0 THEN -delta ELSE 0 END) AS gross_decrease_units, SUM(ABS(delta)) AS gross_movement_units, SUM(delta) AS net_delta_units FROM diffs GROUP BY store_cd, store_name), total AS (SELECT SUM(gross_movement_units) AS total_movement FROM store_agg) SELECT COUNT(*) AS affected_stores, SUM(transitions) AS affected_transitions, SUM(gross_movement_units) AS affected_gross_movement_units, (SELECT total_movement FROM total) AS brand_gross_movement_units, ROUND(100.0*SUM(gross_movement_units)/(SELECT total_movement FROM total),1) AS share_of_brand_movement_pct FROM store_agg WHERE gross_movement_units &gt;= 200000;  *[4]*  - Rows: 1 - Executed at (UTC): 2026-06-11T07:46:32.334Z  