"rich_text_preformatted", "elements": [{"type": "text", "text": "SELECT l.brand, l.store_cd, COALESCE(MAX(d.store_name), MAX(t.store_name)) AS store_name, MAX(d.address) AS address, MAX(t.interval_minutes) AS interval_minutes, COUNT(*) AS scans, SUM(l.item_count) AS item_observations, SUM(l.changed_count) AS changed_observations, ROUND(100.0*SUM(l.changed_count)/NULLIF(SUM(l.item_count),0),2) AS change_rate_pct, MIN(l.checked_at) AS first_scan, MAX(l.checked_at) AS last_scan FROM store_scan_logs l LEFT JOIN store_details d ON d.brand=l.brand AND d.store_cd=l.store_cd LEFT JOIN store_inventory_schedule_targets t ON t.brand=l.brand AND t.store_cd=l.store_cd WHERE l.status=''success'' AND l.checked_at >= ''2026-05-21T00:00:00.000Z'' AND l.checked_at < ''2026-05-27T00:00:00.000Z'' GROUP BY l.brand, l.store_cd HAVING scans >= 20 ORDER BY change_rate_pct DESC, changed_observations DESC LIMIT 20;"}]}]}, {"type": "section", "block_id": "Y0XX5", "text": {"type": "mrkdwn", "text": "*[4]*", "verbatim": false}}, {"type": "rich_text", "block_id": "aJlSR", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 1"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-11T07"}, {"type": "emoji", "name": "27"}, {"type": "text", "text": "06.011Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "IOvbz", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "SELECT checked_at FROM store_scan_logs WHERE status=''success'' ORDER BY checked_at ASC LIMIT 1;"}]}]}, {"type": "section", "block_id": "PUEvO", "text": {"type": "mrkdwn", "text": "*[5]*", "verbatim": false}}, {"type": "rich_text", "block_id": "BerO+", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 1"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-11T07"}, {"type": "emoji", "name": "27"}, {"type": "text", "text": "06.011Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "ie/xO", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "SELECT checked_at FROM store_scan_logs WHERE status=''success'' ORDER BY checked_at DESC LIMIT 1;"}]}]}, {"type": "section", "block_id": "Z3MX6", "text": {"type": "mrkdwn", "text": "*[6]*", "verbatim": false}}, {"type": "rich_text", "block_id": "Im6Kd", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 1"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-11T07"}, {"type": "emoji", "name": "27"}, {"type": "text", "text": "06.011Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "tNPQ0", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "SELECT COUNT(*) AS recent_success_logs FROM store_scan_logs WHERE status=''success'' AND checked_at >= ''2026-06-04T00:00:00.000Z'';"}]}]}, {"type": "section", "block_id": "7hlSK", "text": {"type": "mrkdwn", "text": "*[7]*", "verbatim": false}}, {"type": "rich_text", "block_id": "KUF2r", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 0"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-11T07"}, {"type": "emoji", "name": "29"}, {"type": "text", "text": "06.502Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "eDR7q", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "WITH ordered AS ( SELECT item_cd, on_item_no, item_name, checked_at, stock, LAG(stock) OVER (PARTITION BY item_cd, on_item_no ORDER BY checked_at) AS prev_stock FROM store_inventory_snapshots WHERE brand=''7ELEVEN'' AND store_cd=''68297'' AND checked_at >= ''2026-05-21T00:00:00.000Z'' AND checked_at < ''2026-05-27T00:00:00.000Z'' ), changes AS ( SELECT item_cd, on_item_no, item_name, COUNT(*) AS observations, SUM(CASE WHEN prev_stock IS NOT NULL AND stock != prev_stock THEN 1 ELSE 0 END) AS change_events, SUM(CASE WHEN prev_stock > 0 AND stock=0 THEN 1 ELSE 0 END) AS stockout_events, SUM(CASE WHEN prev_stock=0 AND stock>0 THEN 1 ELSE 0 END) AS restock_events, SUM(CASE WHEN prev_stock IS NOT NULL AND stock < prev_stock THEN prev_stock-stock ELSE 0 END) AS observed_depletion_units, SUM(CASE WHEN prev_stock IS NOT NULL AND stock > prev_stock THEN stock-prev_stock ELSE 0 END) AS observed_restock_units, MIN(stock) AS min_stock, MAX(stock) AS max_stock FROM ordered GROUP BY item_cd, on_item_no, item_name HAVING observations >= 20 ) SELECT * FROM changes ORDER BY stockout_events DESC, observed_depletion_units DESC, change_events DESC LIMIT 50;"}]}]}, {"type": "section", "block_id": "j4U2H", "text": {"type": "mrkdwn", "text": "*[8]*", "verbatim": false}}, {"type": "rich_text", "block_id": "fT0uv", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 1"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-11T07"}, {"type": "emoji", "name": "29"}, {"type": "text", "text": "06.502Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "NcO64", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "WITH ordered AS ( SELECT item_cd, on_item_no, item_name, checked_at, stock, LAG(stock) OVER (PARTITION BY item_cd, on_item_no ORDER BY checked_at) AS prev_stock FROM store_inventory_snapshots WHERE brand=''7ELEVEN'' AND store_cd=''68297'' AND checked_at >= ''2026-05-21T00:00:00.000Z'' AND checked_at < ''2026-05-27T00:00:00.000Z'' ), summary AS ( SELECT COUNT(*) AS transitions, SUM(CASE WHEN prev_stock IS NOT NULL AND stock != prev_stock THEN 1 ELSE 0 END) AS change_events, SUM(CASE WHEN prev_stock > 0 AND stock=0 THEN 1 ELSE 0 END) AS stockout_events, SUM(CASE WHEN prev_stock=0 AND stock>0 THEN 1 ELSE 0 END) AS restock_events, SUM(CASE WHEN prev_stock IS NOT NULL AND stock < prev_stock THEN prev_stock-stock ELSE 0 END) AS observed_depletion_units, SUM(CASE WHEN prev_stock IS NOT NULL AND stock > prev_stock THEN stock-prev_stock ELSE 0 END) AS observed_restock_units, COUNT(DISTINCT item_cd||''|''||on_item_no) AS distinct_items FROM ordered ) SELECT * FROM summary;"}]}]}, {"type": "section", "block_id": "rduz2", "text": {"type": "mrkdwn", "text": "*[9]*", "verbatim": false}}, {"type": "rich_text", "block_id": "m6Z3w", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 1"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-11T07"}, {"type": "emoji", "name": "29"}, {"type": "text", "text": "06.502Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "oV4cd", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "SELECT COUNT(*) AS snapshot_rows, COUNT(DISTINCT item_cd||''|''||on_item_no) AS distinct_items, MIN(checked_at) AS min_checked, MAX(checked_at) AS max_checked FROM store_inventory_snapshots WHERE brand=''7ELEVEN'' AND store_cd=''68297'' AND checked_at >= ''2026-05-21T00:00:00.000Z'' AND checked_at < ''2026-05-27T00:00:00.000Z'';"}]}]}]'),
