insert into briar_channel_messages (id, channel_id, parent_message_id, author_user_id, body, created_at, updated_at, blocks_json)
values
  ('7aa05dab-4480-5bef-8488-f37abf6fa76f', '6c8eb00a-f68f-5306-9d35-ae99f729e52b', '5d91dd50-c592-59f0-b974-aa7c881925c4', 'usr-slack-velen', 'Evidence  *[1]*  - Rows: 7 - Executed at (UTC): 2026-06-10T07:58:50.868Z  WITH latest AS (SELECT brand, store_cd, MAX(id) AS run_id FROM store_inventory_runs WHERE status=''success'' AND finished_at &gt;= ''2026-05-23'' AND finished_at &lt; ''2026-05-30'' GROUP BY brand, store_cd) SELECT r.brand, COUNT(*) AS stores, ROUND(AVG(100.0*s.in_stock_items/NULLIF(s.total_items,0)),1) AS avg_availability_pct, MIN(ROUND(100.0*s.in_stock_items/NULLIF(s.total_items,0),1)) AS min_availability_pct, MAX(ROUND(100.0*s.in_stock_items/NULLIF(s.total_items,0),1)) AS max_availability_pct, ROUND(AVG(s.total_units),1) AS avg_total_units FROM latest l JOIN store_inventory_runs r ON r.id=l.run_id JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE s.total_items&gt;=100 GROUP BY r.brand ORDER BY stores DESC;  *[2]*  - Rows: 1 - Executed at (UTC): 2026-06-10T07:54:01.021Z  SELECT checked_at FROM store_scan_logs ORDER BY checked_at DESC LIMIT 1;  *[3]*  - Rows: 1 - Executed at (UTC): 2026-06-10T07:54:01.021Z  SELECT COUNT(*) AS recent_success_logs FROM store_scan_logs WHERE status=''success'' AND checked_at &gt;= ''2026-06-03'';  *[4]*  - Rows: 50 - Executed at (UTC): 2026-06-10T07:58:50.868Z  WITH latest AS (SELECT brand, store_cd, MAX(id) AS run_id FROM store_inventory_runs WHERE status=''success'' AND finished_at &gt;= ''2026-05-23'' AND finished_at &lt; ''2026-05-30'' GROUP BY brand, store_cd) SELECT r.brand, r.store_cd, r.store_name, s.total_items, s.in_stock_items, s.zero_stock_items, ROUND(100.0*s.in_stock_items/NULLIF(s.total_items,0),1) AS availability_pct, s.total_units, s.max_stock, r.finished_at FROM latest l JOIN store_inventory_runs r ON r.id=l.run_id JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE s.total_items&gt;=100 ORDER BY availability_pct ASC LIMIT 50;  *[5]*  - Rows: 2 - Executed at (UTC): 2026-06-10T07:58:33.073Z  SELECT r.brand, r.store_cd, r.store_name, s.total_items, s.in_stock_items, s.zero_stock_items, s.total_units, s.max_stock, r.finished_at FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.status=''success'' AND r.brand=''EMART24'' AND r.store_cd IN (''04396'',''30430'') ORDER BY r.finished_at DESC LIMIT 20;  *[6]*  - Rows: 2 - Executed at (UTC): 2026-06-10T07:58:33.073Z  SELECT r.brand, r.store_cd, r.store_name, COUNT(*) AS runs, ROUND(AVG(s.total_items),1) AS avg_total_items, ROUND(AVG(s.in_stock_items),1) AS avg_in_stock_items, ROUND(AVG(s.zero_stock_items),1) AS avg_zero_stock_items, ROUND(100.0*AVG(s.in_stock_items)/NULLIF(AVG(s.total_items),0),1) AS avg_availability_pct, ROUND(AVG(s.total_units),1) AS avg_total_units, MIN(r.finished_at) AS first_finished, MAX(r.finished_at) AS last_finished FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.status=''success'' AND r.brand=''EMART24'' AND r.store_cd IN (''04396'',''30430'') AND r.finished_at &gt;= ''2026-05-07'' AND r.finished_at &lt; ''2026-05-30'' GROUP BY r.brand, r.store_cd, r.store_name ORDER BY avg_availability_pct DESC;  *[7]*  - Rows: 50 - Executed at (UTC): 2026-06-10T07:57:58.213Z  SELECT iid.item_name, iid.item_cd, COUNT(*) AS stores_tracked, SUM(CASE WHEN ils.stock&gt;0 THEN 1 ELSE 0 END) AS in_stock_stores, SUM(CASE WHEN ils.stock=0 THEN 1 ELSE 0 END) AS zero_stock_stores, SUM(COALESCE(ils.stock,0)) AS total_units, GROUP_CONCAT(ils.store_cd || '':'' || COALESCE(ils.stock,-1), '', '') AS store_stock, MAX(ils.last_changed_at) AS last_changed FROM inventory_latest_state ils JOIN inventory_item_dimensions iid ON iid.item_key=ils.item_key WHERE ils.brand=''EMART24'' AND ils.store_cd IN (''04396'',''30430'') GROUP BY iid.item_cd, iid.item_name HAVING stores_tracked=2 AND zero_stock_stores=1 AND total_units&gt;=10 ORDER BY total_units DESC LIMIT 50;  *[8]*  - Rows: 50 - Executed at (UTC): 2026-06-10T07:57:58.213Z  SELECT iid.item_name, iid.item_cd, COUNT(*) AS stores_tracked, SUM(CASE WHEN ils.stock&gt;0 THEN 1 ELSE 0 END) AS in_stock_stores, SUM(CASE WHEN ils.stock=0 THEN 1 ELSE 0 END) AS zero_stock_stores, SUM(COALESCE(ils.stock,0)) AS total_un', '2026-06-30T10:00:15.216Z', '2026-06-30T10:00:15.216Z', '[{"type": "header", "block_id": "mAV++", "text": {"type": "plain_text", "text": "Evidence", "emoji": true}}, {"type": "section", "block_id": "E7u/8", "text": {"type": "mrkdwn", "text": "*[1]*", "verbatim": false}}, {"type": "rich_text", "block_id": "OAXWW", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 7"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-10T07"}, {"type": "emoji", "name": "58"}, {"type": "text", "text": "50.868Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "pr7WE", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "WITH latest AS (SELECT brand, store_cd, MAX(id) AS run_id FROM store_inventory_runs WHERE status=''success'' AND finished_at >= ''2026-05-23'' AND finished_at < ''2026-05-30'' GROUP BY brand, store_cd) SELECT r.brand, COUNT(*) AS stores, ROUND(AVG(100.0*s.in_stock_items/NULLIF(s.total_items,0)),1) AS avg_availability_pct, MIN(ROUND(100.0*s.in_stock_items/NULLIF(s.total_items,0),1)) AS min_availability_pct, MAX(ROUND(100.0*s.in_stock_items/NULLIF(s.total_items,0),1)) AS max_availability_pct, ROUND(AVG(s.total_units),1) AS avg_total_units FROM latest l JOIN store_inventory_runs r ON r.id=l.run_id JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE s.total_items>=100 GROUP BY r.brand ORDER BY stores DESC;"}]}]}, {"type": "section", "block_id": "apbbb", "text": {"type": "mrkdwn", "text": "*[2]*", "verbatim": false}}, {"type": "rich_text", "block_id": "u4cJ6", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type"