  ('1dcf7d57-e653-5ff4-90be-d264e5e2a851', 'a4f3887e-60b5-59f9-b4a2-8dd3f57ee239', 'dd77a045-f1ea-5d0b-84c4-8ef589387a5e', 'usr-slack-ian', '넵 해주시면 감사하겠습니다', '2026-07-01T01:21:37.730Z', '2026-07-01T01:21:37.730Z', '[{"type": "rich_text", "block_id": "8Q7o4", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "넵 해주시면 감사하겠습니다"}]}]}]'),
