values
  ('d3a5958c-f4b7-548d-ad77-b49fed52d33d', 'a4f3887e-60b5-59f9-b4a2-8dd3f57ee239', '5bf12749-0bfa-5663-8b54-c2914f8291f2', 'usr-slack-velen', 'SQL used  WITH current_items AS (  SELECT item_key, item_cd, item_name, disp_large_cd  FROM curated_dimensions_v2.provider_items  WHERE provider = ''CU''  AND known_to IS NULL ), promo_items AS (  SELECT DISTINCT  l.item_cd,  o.title AS promotion_title,  o.label,  o.promotion_kind  FROM curated_promotions_v2.offers o  JOIN curated_promotions_v2.offer_item_links l  ON o.provider = l.provider  AND o.offer_key = l.offer_key  WHERE o.provider = ''CU''  AND (o.promotion_kind = ''one_plus_one'' OR o.label = ''1+1'' OR o.title LIKE ''%1+1%'')  AND l.item_cd IS NOT NULL ) SELECT DISTINCT  p.item_cd,  COALESCE(i.item_name, p.promotion_title) AS item_name,  i.disp_large_cd,  SUBSTR(i.disp_large_cd, 1, 2) AS h_class,  ''즉석조리'' AS h_class_label,  p.label,  p.promotion_kind FROM promo_items p JOIN current_items i  ON p.item_cd = i.item_cd WHERE SUBSTR(i.disp_large_cd, 1, 2) = ''02'' ORDER BY item_name, item_cd;  레퍼런스 및 분석 작업 로그: <https://velen.wordbricks.ai/cvs/chat/01KWETYH30AZVMYZEPXVMQEYQG|Velen에서 보기>', '2026-07-01T13:24:49.490Z', '2026-07-01T13:24:49.490Z', '[{"type": "header", "block_id": "aTz5M", "text": {"type": "plain_text", "text": "SQL used", "emoji": true}}, {"type": "rich_text", "block_id": "4ndMK", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "WITH current_items AS (\n SELECT item_key, item_cd, item_name, disp_large_cd\n FROM curated_dimensions_v2.provider_items\n WHERE provider = ''CU''\n AND known_to IS NULL\n),\npromo_items AS (\n SELECT DISTINCT\n l.item_cd,\n o.title AS promotion_title,\n o.label,\n o.promotion_kind\n FROM curated_promotions_v2.offers o\n JOIN curated_promotions_v2.offer_item_links l\n ON o.provider = l.provider\n AND o.offer_key = l.offer_key\n WHERE o.provider = ''CU''\n AND (o.promotion_kind = ''one_plus_one'' OR o.label = ''1+1'' OR o.title LIKE ''%1+1%'')\n AND l.item_cd IS NOT NULL\n)\nSELECT DISTINCT\n p.item_cd,\n COALESCE(i.item_name, p.promotion_title) AS item_name,\n i.disp_large_cd,\n SUBSTR(i.disp_large_cd, 1, 2) AS h_class,\n ''즉석조리'' AS h_class_label,\n p.label,\n p.promotion_kind\nFROM promo_items p\nJOIN current_items i\n ON p.item_cd = i.item_cd\nWHERE SUBSTR(i.disp_large_cd, 1, 2) = ''02''\nORDER BY item_name, item_cd;"}]}]}, {"type": "section", "block_id": "0VipT", "text": {"type": "mrkdwn", "text": "레퍼런스 및 분석 작업 로그: <https://velen.wordbricks.ai/cvs/chat/01KWETYH30AZVMYZEPXVMQEYQG|Velen에서 보기>", "verbatim": false}}]'),
