  ('3b0384b7-3d04-5b72-a02d-1eae31d7b623', 'a4f3887e-60b5-59f9-b4a2-8dd3f57ee239', '12552791-aa9d-5a88-b5d7-3a5e18b79756', 'usr-slack-jay', 'DeviceId 에 cu-cralwer 라고 쓰고 있었음...;;', '2026-07-02T02:46:21.123Z', '2026-07-02T02:46:21.123Z', '[{"type": "rich_text", "block_id": "znVc+", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "DeviceId 에 cu-cralwer 라고 쓰고 있었음...;;"}]}]}]'),
  ('7d84458e-afd8-5d78-a5a5-abfdafe5750e', 'a4f3887e-60b5-59f9-b4a2-8dd3f57ee239', '0fe2cc1f-4473-5b35-bc33-da5ca65d14f0', 'usr-slack-ian', '<@U0BA6CJBUUU>
```
  WITH target_sku AS (
    SELECT
      provider,
      item_key,
      provider_sku_code,
      provider_sku_name
    FROM curated_dimensions_v2.provider_skus
    WHERE provider = ''CU''
      AND known_to IS NULL
      AND (
        item_key = ''여기에_item_key''
        OR provider_sku_code = ''여기에_item_cd''
      )
  )

  SELECT
    s.provider,
    s.item_key,
    s.provider_sku_code,
    s.provider_sku_name,

    l.master_item_code,
    p.master_item_name,

    p.hclass_code,
    p.hclass_name,
    p.mclass_code,
    p.mclass_name,
    p.lclass_code,
    p.lclass_name,

    l.link_type,
    l.match_strategy,
    l.confidence
  FROM target_sku s
  LEFT JOIN curated_dimensions_v2.provider_item_master_links l
    ON l.provider = s.provider
   AND l.provider_item_code = s.provider_sku_code
   AND l.known_to IS NULL
  LEFT JOIN curated_dimensions_v2.provider_product_master_items p
    ON p.provider = l.provider
   AND p.master_item_code = l.master_item_code
   AND p.known_to IS NULL
  ORDER BY l.confidence DESC
  LIMIT 20;```', '2026-07-02T02:50:17.568Z', '2026-07-02T02:50:17.568Z', '[{"type": "rich_text", "block_id": "g8u37", "elements": [{"type": "rich_text_section", "elements": [{"type": "user", "user_id": "U0BA6CJBUUU"}, {"type": "text", "text": "\n"}]}, {"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "\n  WITH target_sku AS (\n    SELECT\n      provider,\n      item_key,\n      provider_sku_code,\n      provider_sku_name\n    FROM curated_dimensions_v2.provider_skus\n    WHERE provider = ''CU''\n      AND known_to IS NULL\n      AND (\n        item_key = ''여기에_item_key''\n        OR provider_sku_code = ''여기에_item_cd''\n      )\n  )\n\n  SELECT\n    s.provider,\n    s.item_key,\n    s.provider_sku_code,\n    s.provider_sku_name,\n\n    l.master_item_code,\n    p.master_item_name,\n\n    p.hclass_code,\n    p.hclass_name,\n    p.mclass_code,\n    p.mclass_name,\n    p.lclass_code,\n    p.lclass_name,\n\n    l.link_type,\n    l.match_strategy,\n    l.confidence\n  FROM target_sku s\n  LEFT JOIN curated_dimensions_v2.provider_item_master_links l\n    ON l.provider = s.provider\n   AND l.provider_item_code = s.provider_sku_code\n   AND l.known_to IS NULL\n  LEFT JOIN curated_dimensions_v2.provider_product_master_items p\n    ON p.provider = l.provider\n   AND p.master_item_code = l.master_item_code\n   AND p.known_to IS NULL\n  ORDER BY l.confidence DESC\n  LIMIT 20;"}], "border": 0}]}]'),
