  ('3ffa0684-2727-5486-a049-82a92ff7fbc8', 'a4f3887e-60b5-59f9-b4a2-8dd3f57ee239', 'b0d721d5-8a24-56cd-b189-7c0849261432', 'usr-slack-jay', '넴 한번 해봐주실래요?', '2026-07-02T04:56:16.768Z', '2026-07-02T04:56:16.768Z', '[{"type": "rich_text", "block_id": "trpsk", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "넴 한번 해봐주실래요?"}]}]}]'),
