insert into briar_channel_messages (id, channel_id, parent_message_id, author_user_id, body, created_at, updated_at, blocks_json)
values
  ('b19c4e5e-85f8-5075-90e4-05596e67b2e7', '6c8eb00a-f68f-5306-9d35-ae99f729e52b', 'fb47493f-46bf-5b42-b0ce-11f3772039f4', 'usr-slack-velen', 'Evidence  *[1]*  - Rows: 7 - Executed at (UTC): 2026-06-08T07:59:57.288Z  SELECT r.brand, COUNT(*) AS runs, COUNT(DISTINCT r.store_cd) AS stores, SUM(s.total_items) AS total_items_seen, SUM(s.in_stock_items) AS in_stock_items, SUM(s.zero_stock_items) AS zero_stock_items, SUM(s.total_units) AS total_units, ROUND(1.0*SUM(s.in_stock_items)/NULLIF(SUM(s.total_items),0),4) AS weighted_in_stock_item_rate, ROUND(AVG(s.total_units),2) AS avg_units_per_run FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.id &gt;= 300000 AND r.status=''success'' GROUP BY r.brand ORDER BY runs DESC LIMIT 20;  *[2]*  - Rows: 17 - Executed at (UTC): 2026-06-08T07:59:57.288Z  SELECT r.brand, date(r.started_at) AS day, COUNT(*) AS runs, COUNT(DISTINCT r.store_cd) AS stores, SUM(s.total_items) AS total_items_seen, SUM(s.in_stock_items) AS in_stock_items, SUM(s.zero_stock_items) AS zero_stock_items, SUM(s.total_units) AS total_units, ROUND(AVG(CASE WHEN s.total_items&gt;0 THEN 1.0*s.in_stock_items/s.total_items END),4) AS avg_in_stock_item_rate, ROUND(AVG(s.total_units),2) AS avg_units_per_run FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.id &gt;= 300000 AND r.status=''success'' GROUP BY r.brand, date(r.started_at) ORDER BY day DESC, r.brand LIMIT 80;  *[3]*  - Rows: 30 - Executed at (UTC): 2026-06-08T08:00:13.280Z  SELECT r.brand, r.store_cd, r.store_name, COUNT(*) AS runs, SUM(s.total_items) AS total_items_seen, SUM(s.in_stock_items) AS in_stock_items, SUM(s.zero_stock_items) AS zero_stock_items, SUM(s.total_units) AS total_units, ROUND(1.0*SUM(s.in_stock_items)/NULLIF(SUM(s.total_items),0),4) AS in_stock_rate, ROUND(AVG(s.total_units),1) AS avg_units_per_run FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.id &gt;= 300000 AND r.status=''success'' AND r.brand=''EMART24'' GROUP BY r.brand, r.store_cd, r.store_name HAVING runs &gt;= 1 ORDER BY total_items_seen DESC LIMIT 30;  *[4]*  - Rows: 1 - Executed at (UTC): 2026-06-08T07:57:04.881Z  SELECT brand, COUNT(*) AS rows, COUNT(DISTINCT store_cd) AS stores, COUNT(DISTINCT item_cd || '':'' || on_item_no) AS items, MIN(checked_at) AS min_checked_at, MAX(checked_at) AS max_checked_at FROM store_inventory_snapshots GROUP BY brand ORDER BY rows DESC LIMIT 20;  *[5]*  - Rows: 1 - Executed at (UTC): 2026-06-08T07:57:04.881Z  SELECT brand, date(checked_at) AS day, COUNT(*) AS snapshot_rows, COUNT(DISTINCT store_cd) AS stores, COUNT(DISTINCT item_cd || '':'' || on_item_no) AS items, SUM(CASE WHEN stock&gt;0 THEN 1 ELSE 0 END) AS in_stock_rows, SUM(CASE WHEN stock=0 THEN 1 ELSE 0 END) AS zero_stock_rows, SUM(COALESCE(stock,0)) AS total_units FROM store_inventory_snapshots GROUP BY brand, date(checked_at) ORDER BY day DESC, brand LIMIT 60;', '2026-07-02T10:00:21.684Z', '2026-07-02T10:00:21.684Z', '[{"type": "header", "block_id": "CYdcA", "text": {"type": "plain_text", "text": "Evidence", "emoji": true}}, {"type": "section", "block_id": "pjluj", "text": {"type": "mrkdwn", "text": "*[1]*", "verbatim": false}}, {"type": "rich_text", "block_id": "H41rR", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 7"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-08T07"}, {"type": "emoji", "name": "59"}, {"type": "text", "text": "57.288Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "U9dM6", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "SELECT r.brand, COUNT(*) AS runs, COUNT(DISTINCT r.store_cd) AS stores, SUM(s.total_items) AS total_items_seen, SUM(s.in_stock_items) AS in_stock_items, SUM(s.zero_stock_items) AS zero_stock_items, SUM(s.total_units) AS total_units, ROUND(1.0*SUM(s.in_stock_items)/NULLIF(SUM(s.total_items),0),4) AS weighted_in_stock_item_rate, ROUND(AVG(s.total_units),2) AS avg_units_per_run FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.id >= 300000 AND r.status=''success'' GROUP BY r.brand ORDER BY runs DESC LIMIT 20;"}]}]}, {"type": "section", "block_id": "W3oLL", "text": {"type": "mrkdwn", "text": "*[2]*", "verbatim": false}}, {"type": "rich_text", "block_id": "vkWQm", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 17"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-08T07"}, {"type": "emoji", "name": "59"}, {"type": "text", "text": "57.288Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "SQ1hT", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "SELECT r.brand, date(r.started_at) AS day, COUNT(*) AS runs, COUNT(DISTINCT r.store_cd) AS stores, SUM(s.total_items) AS total_items_seen, SUM(s.in_stock_items) AS in_stock_items, SUM(s.zero_stock_items) AS zero_stock_items, SUM(s.total_units) AS total_units, ROUND(AVG(CASE WHEN s.total_items>0 THEN 1.0*s.in_stock_items/s.total_items END),4) AS avg_in_stock_item_rate, ROUND(AVG(s.total_units),2) AS avg_units_per_run FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.id >= 300000 AND r.status=''success'' GROUP BY r.brand, date(r.started_at) ORDER BY day DESC, r.brand LIMIT 80;"}]}]}, {"type": "section", "block_id": "5U/W2", "text": {"type": "mrkdwn", "text": "*[3]*", "verbatim": false}}, {"type": "rich_text", "block_id": "+sppx", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 30"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-08T08"}, {"type": "emoji", "name": "00"}, {"type": "text", "text": "13.280Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "KGB2a", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "SELECT r.brand, r.store_cd, r.store_name, COUNT(*) AS runs, SUM(s.total_items) AS total_items_seen, SUM(s.in_stock_items) AS in_stock_items, SUM(s.zero_stock_items) AS zero_stock_items, SUM(s.total_units) AS total_units, ROUND(1.0*SUM(s.in_stock_items)/NULLIF(SUM(s.total_items),0),4) AS in_stock_rate, ROUND(AVG(s.total_units),1) AS avg_units_per_run FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.id >= 300000 AND r.status=''success'' AND r.brand=''EMART24'' GROUP BY r.brand, r.store_cd, r.store_name HAVING runs >= 1 ORDER BY total_items_seen DESC LIMIT 30;"}]}]}, {"type": "section", "block_id": "gPZG9", "text": {"type": "mrkdwn", "text": "*[4]*", "verbatim": false}}, {"type": "rich_text", "block_id": "Jg888", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 1"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-08T07"}, {"type": "emoji", "name": "57"}, {"type": "text", "text": "04.881Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "fIpsf", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "SELECT brand, COUNT(*) AS rows, COUNT(DISTINCT store_cd) AS stores, COUNT(DISTINCT item_cd || '':'' || on_item_no) AS items, MIN(checked_at) AS min_checked_at, MAX(checked_at) AS max_checked_at FROM store_inventory_snapshots GROUP BY brand ORDER BY rows DESC LIMIT 20;"}]}]}, {"type": "section", "block_id": "jPokv", "text": {"type": "mrkdwn", "text": "*[5]*", "verbatim": false}}, {"type": "rich_text", "block_id": "6cNkS", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 1"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-08T07"}, {"type": "emoji", "name": "57"}, {"type": "text", "text": "04.881Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "NpB0n", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "SELECT brand, date(checked_at) AS day, COUNT(*) AS snapshot_rows, COUNT(DISTINCT store_cd) AS stores, COUNT(DISTINCT item_cd || '':'' || on_item_no) AS items, SUM(CASE WHEN stock>0 THEN 1 ELSE 0 END) AS in_stock_rows, SUM(CASE WHEN stock=0 THEN 1 ELSE 0 END) AS zero_stock_rows, SUM(COALESCE(stock,0)) AS total_units FROM store_inventory_snapshots GROUP BY brand, date(checked_at) ORDER BY day DESC, brand LIMIT 60;"}]}]}]'),
