insert into briar_channel_messages (id, channel_id, parent_message_id, author_user_id, body, created_at, updated_at, blocks_json)
values
  ('96a88390-36f9-5d01-bd55-02aafc173d90', '6c8eb00a-f68f-5306-9d35-ae99f729e52b', '36b2ff9a-0cef-5df4-b5f8-93386385f2c7', 'usr-slack-velen', 'Evidence  *[1]*  - Rows: 30 - Executed at (UTC): 2026-06-08T07:14:22.446Z  WITH daily AS (SELECT substr(r.started_at,1,10) dt, r.brand, r.store_cd, r.store_name, r.id run_id, r.started_at, s.total_items, s.in_stock_items, s.zero_stock_items, s.total_units, ROW_NUMBER() OVER (PARTITION BY substr(r.started_at,1,10), r.brand, r.store_cd ORDER BY r.started_at DESC) rn FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.started_at &gt;= ''2026-05-23'' AND r.started_at &lt; ''2026-05-30'' AND s.total_items &gt;= 50), last_daily AS (SELECT * FROM daily WHERE rn=1), first_last AS (SELECT brand, store_cd, store_name, COUNT(*) AS days_observed, MIN(dt) first_dt, MAX(dt) last_dt FROM last_daily GROUP BY brand, store_cd HAVING COUNT(*) &gt;= 3), joined AS (SELECT fl.brand, fl.store_cd, fl.store_name, fl.days_observed, f.total_items first_items, l.total_items last_items, f.in_stock_items first_in_stock, l.in_stock_items last_in_stock, f.total_units first_units, l.total_units last_units, (l.total_units - f.total_units) unit_change, ROUND(100.0*(l.total_units - f.total_units)/NULLIF(f.total_units,0),1) pct_unit_change, ROUND(100.0*l.in_stock_items/l.total_items,1) last_in_stock_rate FROM first_last fl JOIN last_daily f ON f.brand=fl.brand AND f.store_cd=fl.store_cd AND f.dt=fl.first_dt JOIN last_daily l ON l.brand=fl.brand AND l.store_cd=fl.store_cd AND l.dt=fl.last_dt WHERE ABS(l.total_items - f.total_items) &lt;= 0.1*f.total_items AND f.total_units &gt; 0) SELECT * FROM joined ORDER BY unit_change ASC LIMIT 30;  *[2]*  - Rows: 89 - Executed at (UTC): 2026-06-08T07:13:46.757Z  SELECT substr(r.started_at,1,10) AS dt, r.brand, COUNT(*) AS runs, COUNT(DISTINCT r.store_cd) AS stores, SUM(s.total_items) AS total_sku_obs, SUM(s.in_stock_items) AS in_stock_sku_obs, SUM(s.zero_stock_items) AS zero_stock_sku_obs, SUM(s.total_units) AS total_units, AVG(CASE WHEN s.total_items&gt;0 THEN 1.0*s.in_stock_items/s.total_items END) AS avg_in_stock_rate FROM store_inventory_run_summaries s JOIN store_inventory_runs r ON r.id=s.run_id WHERE r.started_at &gt;= ''2026-05-07'' AND r.started_at &lt; ''2026-05-30'' GROUP BY dt, r.brand ORDER BY dt, r.brand LIMIT 500;  *[3]*  - Rows: 0 - Executed at (UTC): 2026-06-08T07:14:39.974Z  WITH runs AS (SELECT r.id, substr(r.started_at,1,10) dt, r.started_at, ROW_NUMBER() OVER (PARTITION BY substr(r.started_at,1,10), r.store_cd ORDER BY r.started_at DESC) rn FROM store_inventory_runs r WHERE r.brand=''OLIVEYOUNG'' AND r.store_cd=''DE93'' AND r.started_at &gt;= ''2026-05-27'' AND r.started_at &lt; ''2026-05-30''), endpoints AS (SELECT id, dt FROM runs WHERE rn=1 AND dt IN ((SELECT MIN(dt) FROM runs WHERE rn=1),(SELECT MAX(dt) FROM runs WHERE rn=1))), pivot AS (SELECT s.item_cd, s.on_item_no, MAX(s.item_name) item_name, MAX(CASE WHEN e.dt=(SELECT MIN(dt) FROM endpoints) THEN s.stock END) first_stock, MAX(CASE WHEN e.dt=(SELECT MAX(dt) FROM endpoints) THEN s.stock END) last_stock, MAX(CASE WHEN e.dt=(SELECT MIN(dt) FROM endpoints) THEN s.sale_price END) sale_price FROM store_inventory_snapshots s JOIN endpoints e ON e.id=s.run_id GROUP BY s.item_cd, s.on_item_no HAVING first_stock IS NOT NULL AND last_stock IS NOT NULL) SELECT item_cd, on_item_no, item_name, sale_price, first_stock, last_stock, (last_stock-first_stock) AS stock_change FROM pivot ORDER BY stock_change ASC LIMIT 50;  *[4]*  - Rows: 0 - Executed at (UTC): 2026-06-08T07:14:39.974Z  WITH runs AS (SELECT r.id, substr(r.started_at,1,10) dt, r.started_at, ROW_NUMBER() OVER (PARTITION BY substr(r.started_at,1,10), r.store_cd ORDER BY r.started_at DESC) rn FROM store_inventory_runs r WHERE r.brand=''OLIVEYOUNG'' AND r.store_cd=''DE93'' AND r.started_at &gt;= ''2026-05-27'' AND r.started_at &lt; ''2026-05-30''), endpoints AS (SELECT id, dt FROM runs WHERE rn=1 AND dt IN ((SELECT MIN(dt) FROM runs WHERE rn=1),(SELECT MAX(dt) FROM runs WHERE rn=1))), pivot AS (SELECT s.disp_large_cd, COUNT(*) sku_count, SUM(CASE WHEN e.dt=(SELECT MIN(dt) FROM endpoints) THEN s.stock ELSE 0 END) first_units, SUM(C', '2026-07-03T10:00:16.225Z', '2026-07-03T10:00:16.225Z', '[{"type": "header", "block_id": "i3ocY", "text": {"type": "plain_text", "text": "Evidence", "emoji": true}}, {"type": "section", "block_id": "hLjHw", "text": {"type": "mrkdwn", "text": "*[1]*", "verbatim": false}}, {"type": "rich_text", "block_id": "VViKr", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 30"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-08T07"}, {"type": "emoji", "name": "14"}, {"type": "text", "text": "22.446Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "QlArL", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "WITH daily AS (SELECT substr(r.started_at,1,10) dt, r.brand, r.store_cd, r.store_name, r.id run_id, r.started_at, s.total_items, s.in_stock_items, s.zero_stock_items, s.total_units, ROW_NUMBER() OVER (PARTITION BY substr(r.started_at,1,10), r.brand, r.store_cd ORDER BY r.started_at DESC) rn FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.started_at >= ''2026-05-23'' AND r.started_at < ''2026-05-30'' AND s.total_items >= 50), last_daily AS (SELECT * FROM daily WHERE rn=1), first_last AS (SELECT brand, store_cd, store_name, COUNT(*) AS days_observed, MIN(dt) first_dt, MAX(dt) last_dt FROM last_daily GROUP BY brand, store_cd HAVING COUNT(*) >= 3), joined AS (SELECT fl.brand, fl.store_cd, fl.store_name, fl.days_observed, f.total_items first_items, l.total_items last_items, f.in_stock_items first_in_stock, l.in_stock_items last_in_stock, f.total_units first_units, l.total_units last_units, (l.total_units - f.total_units) unit_change, ROUND(100.0*(l.total_units - f.total_units)/NULLIF(f.total_units,0),1) pct_unit_change, ROUND(100.0*l.in_stock_items/l.total_items,1) last_in_stock_rate FROM first_last fl JOIN last_daily f ON f.brand=fl.brand AND f.store_cd=fl.store_cd AND f.dt=fl.first_dt JOIN last_daily l ON l.brand=fl.brand AND l.store_cd=fl.store_cd AND l.dt=fl.last_dt WHERE ABS(l.total_items - f.total_items) <= 0.1*f.total_items AND f.total_units > 0) SELECT * FROM joined ORDER BY unit_change ASC LIMIT 30;"}]}]}, {"type": "section", "block_id": "ubsYG", "text": {"type": "mrkdwn", "text": "*[2]*", "verbatim": false}}, {"type": "rich_text", "block_id": "k1KaF", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 89"}]}, {"type": "rich_text_section", "elements": [{"type": "text", "text": "Executed at (UTC): 2026-06-08T07"}, {"type": "emoji", "name": "13"}, {"type": "text", "text": "46.757Z"}]}], "style": "bullet", "indent": 0}]}, {"type": "rich_text", "block_id": "Qx/FI", "elements": [{"type": "rich_text_preformatted", "elements": [{"type": "text", "text": "SELECT substr(r.started_at,1,10) AS dt, r.brand, COUNT(*) AS runs, COUNT(DISTINCT r.store_cd) AS stores, SUM(s.total_items) AS total_sku_obs, SUM(s.in_stock_items) AS in_stock_sku_obs, SUM(s.zero_stock_items) AS zero_stock_sku_obs, SUM(s.total_units) AS total_units, AVG(CASE WHEN s.total_items>0 THEN 1.0*s.in_stock_items/s.total_items END) AS avg_in_stock_rate FROM store_inventory_run_summaries s JOIN store_inventory_runs r ON r.id=s.run_id WHERE r.started_at >= ''2026-05-07'' AND r.started_at < ''2026-05-30'' GROUP BY dt, r.brand ORDER BY dt, r.brand LIMIT 500;"}]}]}, {"type": "section", "block_id": "7gLB4", "text": {"type": "mrkdwn", "text": "*[3]*", "verbatim": false}}, {"type": "rich_text", "block_id": "uczfl", "elements": [{"type": "rich_text_list", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "Rows: 0"}]}, {"type": "rich_text_section", "el