insert into briar_channel_messages (id, channel_id, parent_message_id, author_user_id, body, created_at, updated_at, blocks_json)
values
  ('1b14cb2d-b2eb-5c0e-8d9c-f2b095abfcb7', '6c8eb00a-f68f-5306-9d35-ae99f729e52b', '68c8c498-bc47-54e6-adb3-a4aa02a3d73d', 'usr-slack-velen', 'Evidence  *[1]*  - Rows: 6 - Executed at (UTC): 2026-06-07T07:56:07.761Z  SELECT substr(r.started_at,1,10) AS dt, r.brand AS brand, COUNT(*) AS runs, COUNT(DISTINCT r.store_cd) AS stores, SUM(CASE WHEN r.status=''success'' THEN 1 ELSE 0 END) AS success_runs, SUM(s.total_items) AS total_items, SUM(s.in_stock_items) AS in_stock_items, SUM(s.zero_stock_items) AS zero_stock_items, SUM(s.total_units) AS total_units, ROUND(SUM(s.in_stock_items)*100.0/NULLIF(SUM(s.total_items),0),2) AS weighted_in_stock_rate_pct, ROUND(SUM(s.zero_stock_items)*100.0/NULLIF(SUM(s.total_items),0),2) AS weighted_zero_stock_rate_pct FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.started_at &gt;= ''2026-05-27'' AND r.started_at &lt; ''2026-05-30'' AND r.brand IN (''TOUSLESJOURS'',''OLIVEYOUNG'') AND s.total_items &gt; 0 GROUP BY dt, r.brand ORDER BY r.brand, dt;  *[2]*  - Rows: 3 - Executed at (UTC): 2026-06-07T07:54:46.769Z  WITH per AS (SELECT r.brand, r.store_cd, r.store_name, substr(r.started_at,1,10) dt, AVG(s.in_stock_items*1.0/NULLIF(s.total_items,0)) in_stock_rate, AVG(s.total_units) avg_units, COUNT(*) runs FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.id&gt;=350000 AND r.brand=''TOUSLESJOURS'' AND s.total_items&gt;0 GROUP BY r.brand,r.store_cd,r.store_name,dt), agg AS (SELECT dt, COUNT(*) stores, AVG(in_stock_rate) avg_in_stock_rate, AVG(avg_units) avg_units_per_store, SUM(runs) runs FROM per GROUP BY dt) SELECT * FROM agg ORDER BY dt;  *[3]*  - Rows: 3 - Executed at (UTC): 2026-06-07T07:54:46.769Z  WITH per AS (SELECT r.brand, r.store_cd, r.store_name, substr(r.started_at,1,10) dt, AVG(s.in_stock_items*1.0/NULLIF(s.total_items,0)) in_stock_rate, AVG(s.total_units) avg_units, COUNT(*) runs FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.id&gt;=350000 AND r.brand=''OLIVEYOUNG'' AND s.total_items&gt;0 GROUP BY r.brand,r.store_cd,r.store_name,dt), agg AS (SELECT dt, COUNT(*) stores, AVG(in_stock_rate) avg_in_stock_rate, AVG(avg_units) avg_units_per_store, SUM(runs) runs FROM per GROUP BY dt) SELECT * FROM agg ORDER BY dt;  *[4]*  - Rows: 20 - Executed at (UTC): 2026-06-07T07:54:31.628Z  WITH per AS (SELECT r.brand, r.store_cd, r.store_name, substr(r.started_at,1,10) dt, AVG(s.in_stock_items*1.0/NULLIF(s.total_items,0)) in_stock_rate, AVG(s.total_units) avg_units, COUNT(*) runs FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.id&gt;=350000 AND r.brand IN (''OLIVEYOUNG'',''TOUSLESJOURS'') AND s.total_items&gt;0 GROUP BY r.brand,r.store_cd,r.store_name,dt), piv AS (SELECT brand, store_cd, store_name, MAX(CASE WHEN dt=''2026-05-27'' THEN in_stock_rate END) r27, MAX(CASE WHEN dt=''2026-05-29'' THEN in_stock_rate END) r29, MAX(CASE WHEN dt=''2026-05-27'' THEN avg_units END) u27, MAX(CASE WHEN dt=''2026-05-29'' THEN avg_units END) u29, SUM(runs) total_runs FROM per GROUP BY brand, store_cd, store_name) SELECT *, (r29-r27) rate_delta, (u29-u27) units_delta FROM piv WHERE r27 IS NOT NULL AND r29 IS NOT NULL ORDER BY rate_delta DESC LIMIT 20;  *[5]*  - Rows: 1 - Executed at (UTC): 2026-06-07T07:56:07.761Z  SELECT ''join_check'' AS check_name, COUNT(*) AS row_count, COUNT(DISTINCT r.id) AS distinct_run_count, ROUND(COUNT(*)*1.0/NULLIF(COUNT(DISTINCT r.id),0),4) AS row_per_run FROM store_inventory_runs r JOIN store_inventory_run_summaries s ON s.run_id=r.id WHERE r.started_at &gt;= ''2026-05-27'' AND r.started_at &lt; ''2026-05-30'' AND r.brand IN (''TOUSLESJOURS'',''OLIVEYOUNG'') AND s.total_items &gt; 0;', '2026-07-05T10:00:14.797Z', '2026-07-05T10:00:14.797Z', '[{"type": "header", "block_id": "YWZNT", "text": {"type": "plain_text", "text": "Evidence", "emoji": true}}, {"type": "section", "block_id": "7j2CT", "text": {"type": "mrkdwn", "text": "*[1]*",