  ('d2806119-f08f-59e4-91dd-8b936dcae864', 'a4f3887e-60b5-59f9-b4a2-8dd3f57ee239', '06feb91f-0eb9-5e50-9349-e323daa9af12', 'usr-slack-jay', '''저 매장들이 7월에는 안 긁고 있는걸까요?'' -&gt; 저 매장들이 7월에 긁고 있는 430개 안에 안들어가는거 같아요', '2026-07-07T09:41:31.317Z', '2026-07-07T09:41:31.317Z', '[{"type": "rich_text", "block_id": "OhYuK", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "''저 매장들이 7월에는 안 긁고 있는걸까요?'' -> 저 매장들이 7월에 긁고 있는 430개 안에 안들어가는거 같아요"}]}]}]'),
  ('83a211b1-c26e-5dfd-bd68-265710ba22a7', 'a4f3887e-60b5-59f9-b4a2-8dd3f57ee239', 'b768c4f5-6fc8-550b-aec0-f55a05883dcb', 'usr-slack-jay', '전부다 일평균이에요', '2026-07-07T09:44:42.881Z', '2026-07-07T09:44:42.881Z', '[{"type": "rich_text", "block_id": "IoZMd", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "전부다 일평균이에요"}]}]}]'),
