insert into briar_channel_messages (id, channel_id, parent_message_id, author_user_id, body, created_at, updated_at, blocks_json)
values
  ('fc250dde-349e-53dc-b3f8-1bd13d5d2b22', '6c8eb00a-f68f-5306-9d35-ae99f729e52b', 'e84e0fc1-25df-5ee2-b9f0-a6fdb3447246', 'usr-slack-velen', 'Evidence  *[1]*  - Rows: 4 - Executed at (UTC): 2026-06-06T08:52:54.538Z  WITH store_stats AS (SELECT brand, store_cd, COUNT(*) scans, SUM(item_count) item_checks, SUM(changed_count) changed_items, ROUND(100.0*SUM(changed_count)/NULLIF(SUM(item_count),0),3) change_rate_pct, MIN(checked_at) first_scan, MAX(checked_at) last_scan FROM store_scan_logs WHERE status=''success'' AND checked_at &gt;= ''2026-05-18'' AND checked_at &lt; ''2026-05-27'' GROUP BY brand, store_cd HAVING scans &gt;= 20 AND item_checks &gt;= 10000) SELECT brand, COUNT(*) stores, SUM(scans) scans, SUM(item_checks) item_checks, SUM(changed_items) changed_items, ROUND(100.0*SUM(changed_items)/NULLIF(SUM(item_checks),0),3) weighted_change_rate_pct, ROUND(AVG(change_rate_pct),3) avg_store_change_rate_pct, MIN(change_rate_pct) min_store_rate, MAX(change_rate_pct) max_store_rate FROM store_stats GROUP BY brand ORDER BY weighted_change_rate_pct DESC;  *[2]*  - Rows: 4 - Executed at (UTC): 2026-06-06T08:53:15.092Z  WITH brand_totals AS (SELECT brand, SUM(item_count) item_checks, SUM(changed_count) changed_items FROM store_scan_logs WHERE status=''success'' AND checked_at &gt;= ''2026-05-18'' AND checked_at &lt; ''2026-05-27'' GROUP BY brand), station_hospital AS (SELECT l.brand, SUM(l.item_count) item_checks, SUM(l.changed_count) changed_items, COUNT(DISTINCT l.store_cd) stores, COUNT(*) scans FROM store_scan_logs l JOIN store_details d ON d.brand=l.brand AND d.store_cd=l.store_cd WHERE l.status=''success'' AND l.checked_at &gt;= ''2026-05-18'' AND l.checked_at &lt; ''2026-05-27'' AND (d.store_name LIKE ''%역%'' OR d.store_name LIKE ''%병원%'' OR d.store_name LIKE ''%대학교%'' OR d.store_name LIKE ''%한강%'' OR d.store_name LIKE ''%터미널%'') GROUP BY l.brand) SELECT b.brand, b.item_checks all_item_checks, b.changed_items all_changed_items, ROUND(100.0*b.changed_items/NULLIF(b.