  ('4b8c7d8a-28de-5f10-b87c-00cbfb775490', 'a4f3887e-60b5-59f9-b4a2-8dd3f57ee239', 'a520d37b-766a-54eb-9d2b-296855ec7a98', 'usr-slack-ian', '1시간내로해볼게요', '2026-07-08T02:52:49.633Z', '2026-07-08T02:52:49.633Z', '[{"type": "rich_text", "block_id": "jGsba", "elements": [{"type": "rich_text_section", "elements": [{"type": "text", "text": "1시간내로해볼게요"}]}]}]'),
